from document import _HISTORY_REPLAY_CAPABILITY  # noqa: E402


def _apply_history_patch(doc: Any, patch: Any, *, actor: Any) -> None:
    doc.apply_patch_directly(
        patch,
        actor=actor,
        _replay_capability=_HISTORY_REPLAY_CAPABILITY,
    )


# ==============================================================
# GateResult
# ==============================================================

@dataclass(frozen=True)
class GateResult:
    gate_id: str
    name: str
    status: str       # PASS | FAIL | SKIP
    msg: str = ""
    evidence: dict[str, Any] | None = None


def _ok(gate_id: str, name: str, msg: str = "") -> GateResult:
    return GateResult(gate_id=gate_id, name=name, status="PASS", msg=msg)


def _fail(gate_id: str, name: str, msg: str, evidence: dict | None = None) -> GateResult:
    return GateResult(gate_id=gate_id, name=name, status="FAIL", msg=msg, evidence=evidence)


def _skip(gate_id: str, name: str, msg: str = "") -> GateResult:
    return GateResult(gate_id=gate_id, name=name, status="SKIP", msg=msg)


# ==============================================================
# Surface-aware static gate inputs
# ==============================================================

_AUDIT_SURFACES = frozenset(("cli", "api", "web", "mcp"))
_AUDIT_PRIMARY_SURFACES = frozenset(("cli", "api", "web"))


@dataclass(frozen=True)
class AuditSurfaceScope:
    """Validated capability scope consumed by cross-surface audit gates.

    ``ZE_SURFACE.json`` is the authority.  Audit gates deliberately do not
    infer Web/API capability from whichever directories happen to survive a
    managed-core copy: doing so makes a valid headless target fail merely
    because Web sources were correctly omitted.
    """

    skill_root: Path
    surfaces: frozenset[str]
    web_root: Path | None
    server_file: Path | None

    @property
    def has_web(self) -> bool:
        return "web" in self.surfaces

    @property
    def requires_http_server(self) -> bool:
        return bool(self.surfaces.intersection(("api", "web")))


def _declared_relative_path(value: Any, *, field: str) -> Path:
    raw = value.strip() if isinstance(value, str) else ""
    path = Path(raw) if raw else None
    if (
        path is None
        or path.is_absolute()
        or path in (Path("."), Path(".."))
        or ".." in path.parts
    ):
        raise ValueError(f"{field} must be a safe relative path")
    return path


def load_audit_surface_scope(root: Path | None = None) -> AuditSurfaceScope:
    """Load the exact declared surface set without filesystem inference."""
    import json

    skill_root = Path(root) if root is not None else _CORE.parent
    profile_path = skill_root / "ZE_SURFACE.json"
    try:
        profile = json.loads(profile_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ValueError("ZE_SURFACE.json is missing") from exc
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"ZE_SURFACE.json is unreadable or invalid JSON: {exc}") from exc
    if not isinstance(profile, dict):
        raise ValueError("ZE_SURFACE.json must contain an object")
    if profile.get("schema") != "ze.surface_profile.v1":
        raise ValueError("ZE_SURFACE.json schema must be ze.surface_profile.v1")

    raw_surfaces = profile.get("surfaces")
    if (
        not isinstance(raw_surfaces, list)
        or not raw_surfaces
        or any(not isinstance(value, str) for value in raw_surfaces)
    ):
        raise ValueError("ZE_SURFACE.json surfaces must be a non-empty string array")
    if len(set(raw_surfaces)) != len(raw_surfaces):
        raise ValueError("ZE_SURFACE.json surfaces must not contain duplicates")
    unknown = sorted(set(raw_surfaces) - _AUDIT_SURFACES)
    if unknown:
        raise ValueError(f"ZE_SURFACE.json declares unknown surfaces: {unknown}")
    surfaces = frozenset(raw_surfaces)
    primary = profile.get("primary")
    if primary not in _AUDIT_PRIMARY_SURFACES or primary not in surfaces:
        raise ValueError("ZE_SURFACE.json primary must be cli/api/web and belong to surfaces")
    if "mcp" in surfaces and not surfaces.intersection(("api", "web")):
        raise ValueError("ZE_SURFACE.json mcp surface requires an api/web host")

    entrypoints = profile.get("entrypoints")
    if not isinstance(entrypoints, dict):
        raise ValueError("ZE_SURFACE.json entrypoints must be an object")

    web_root: Path | None = None
    if "web" in surfaces:
        web = profile.get("web")
        if not isinstance(web, dict):
            raise ValueError("ZE_SURFACE.json web surface requires a web object")
        web_rel = _declared_relative_path(
            web.get("dir") or entrypoints.get("web"), field="web.dir",
        )
        web_root = skill_root / web_rel

    server_file: Path | None = None
    if surfaces.intersection(("api", "web")):
        api = profile.get("api")
        api_server = api.get("server") if isinstance(api, dict) else None
        # A web-only workbench still uses the framework's conventional HTTP
        # entrypoint even when it does not repeat an ``api`` surface block.
        server_rel = _declared_relative_path(
            api_server or entrypoints.get("api") or "server.py",
            field="api.server",
        )
        server_file = skill_root / server_rel

    return AuditSurfaceScope(
        skill_root=skill_root,
        surfaces=surfaces,
        web_root=web_root,
        server_file=server_file,
    )


def _gate_surface_scope(
    gate_id: str,
    name: str,
    root: Path | None,
) -> tuple[AuditSurfaceScope | None, GateResult | None]:
    try:
        return load_audit_surface_scope(root), None
    except ValueError as exc:
        return None, _fail(gate_id, name, f"invalid surface profile: {exc}")


def _read_gate_sources(
    gate_id: str,
    name: str,
    sources: dict[str, Path],
) -> tuple[dict[str, str], GateResult | None]:
    """Read only sources required by the declared surfaces, failing cleanly."""
    loaded: dict[str, str] = {}
    for label, path in sources.items():
        try:
            loaded[label] = path.read_text(encoding="utf-8")
        except FileNotFoundError:
            return {}, _fail(
                gate_id, name,
                f"declared surface requires missing {label} source: {path}",
            )
        except OSError as exc:
            return {}, _fail(
                gate_id, name,
                f"could not read required {label} source {path}: {exc}",
            )
    return loaded, None


