# ---- DOC ----

def check_doc_01_version_conflict() -> GateResult:
    """save(expected_version=N) != _v 抛 version_conflict."""
    import tempfile
    from document import Document
    from entity import ZeError
    with tempfile.TemporaryDirectory() as td:
        doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
        path = Path(td) / "document.json"
        doc.save(path)   # _v=1→2
        # 用过时的 expected_version
        try:
            doc.save(path, expected_version=99)
            return _fail("GATE-DOC-01", "document_version_conflict",
                         "expected version_conflict but save succeeded")
        except ZeError as e:
            if e.code != "version_conflict":
                return _fail("GATE-DOC-01", "document_version_conflict",
                             f"wrong error code: {e.code}")
    return _ok("GATE-DOC-01", "document_version_conflict")


def check_doc_02_collections_index_consistent() -> GateResult:
    """save 后 document.json collections 索引对应的 entity 文件都存在."""
    import json
    import tempfile
    from document import Document
    from entity import Entity
    from entity_file_store import ENTITY_STORE_DIRECTORY, entity_identity_digest
    with tempfile.TemporaryDirectory() as td:
        doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
        doc.add(Entity(type="obj", data={}, id="e1"))
        doc.add(Entity(type="obj", data={}, id="e2"))
        path = Path(td) / "document.json"
        doc.save(path)
        raw = json.loads(path.read_text())
        for et, ids in (raw.get("collections") or {}).items():
            for eid in ids:
                digest = entity_identity_digest(et, eid)
                ent_file = (
                    Path(td) / "entities" / ENTITY_STORE_DIRECTORY
                    / str(raw["_v"]) / digest[:2] / f"{digest}.json"
                )
                if not ent_file.exists():
                    return _fail("GATE-DOC-02", "document_collections_index_consistent",
                                 f"index points to missing {ent_file}")
    return _ok("GATE-DOC-02", "document_collections_index_consistent")


def check_doc_05_save_policy_declared(root: Path | None = None) -> GateResult:
    """mod 必须用字面量显式声明安全的自动保存策略。"""
    import ast

    skill_root = root or _CORE.parent
    source = skill_root / "02-mod" / "05-code" / "document_register.py"
    name = "save_policy_explicit_and_safe"
    if not source.is_file():
        return _fail("GATE-DOC-05", name, f"missing {source}")
    try:
        tree = ast.parse(source.read_text(encoding="utf-8"), filename=str(source))
    except (OSError, SyntaxError) as exc:
        return _fail("GATE-DOC-05", name, f"document_register unreadable: {exc}")

    declarations: list[str | None] = []
    for node in ast.walk(tree):
        if not (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "set_save_policy"
        ):
            continue
        value_node = node.args[0] if node.args else next(
            (kw.value for kw in node.keywords if kw.arg == "policy"), None
        )
        declarations.append(
            value_node.value
            if isinstance(value_node, ast.Constant) and isinstance(value_node.value, str)
            else None
        )

    if len(declarations) != 1:
        return _fail(
            "GATE-DOC-05", name,
            "document_register must declare save_policy exactly once",
            {"declarations": declarations},
        )
    if declarations[0] not in ("auto_commit", "checkpoint_commit"):
        return _fail(
            "GATE-DOC-05", name,
            "save_policy must be literal auto_commit or checkpoint_commit",
            {"declared": declarations[0]},
        )
    return _ok("GATE-DOC-05", name, f"declared={declarations[0]}")


def check_doc_06_read_only_overlay_atomic_identity() -> GateResult:
    """只读 source 晚冲突不得覆盖 canonical 或留下半批 materialization."""
    from document import Document, ReadOnlySourceSpec
    from entity import Entity, ZeError

    name = "read_only_overlay_atomic_identity"
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    canonical = Entity(type="level", id="same", data={"owner": "canonical"})
    doc.add(canonical)
    try:
        doc.register_read_only_source(ReadOnlySourceSpec(
            name="external",
            entity_type="level",
            loader=lambda: [
                {"id": "new", "data": {"owner": "overlay"}},
                {"id": "same", "data": {"owner": "overlay"}},
            ],
        ))
        return _fail("GATE-DOC-06", name, "identity conflict was accepted")
    except ZeError as exc:
        if (
            exc.code != "validation_failed"
            or exc.context.get("reason") != "read_only_source_identity_conflict"
        ):
            return _fail(
                "GATE-DOC-06", name,
                f"wrong conflict projection: {exc.code}/{exc.context.get('reason')}",
            )

    if doc.find("level", "same") is not canonical:
        return _fail("GATE-DOC-06", name, "canonical object identity was replaced")
    if canonical.data != {"owner": "canonical"}:
        return _fail("GATE-DOC-06", name, "canonical data was overwritten")
    if doc.find("level", "new") is not None or doc.read_only_sources():
        return _fail("GATE-DOC-06", name, "failed registration left partial state")
    return _ok("GATE-DOC-06", name)


def check_doc_07_safe_entity_file_store() -> GateResult:
    """v2 identities, legacy migration, unsafe cleanup and commit truth agree."""
    import json
    import os
    import tempfile

    import entity_file_store as store_module
    from document import Document
    from entity import Entity, ZeError
    from entity_file_store import (
        ENTITY_STORE_DIRECTORY,
        EntityFileStoreError,
        entity_identity_digest,
    )

    gate_id = "GATE-DOC-07"
    name = "safe_entity_file_store_commit_boundary"
    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        path = root / "document.json"
        hostile_type = "../type/../../outside"
        hostile_id = "/absolute/实体"
        doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
        doc.add(Entity(type=hostile_type, id=hostile_id, data={"value": 1}))
        try:
            doc.save(path)
            reopened = Document.open(path)
        except ZeError as exc:
            return _fail(gate_id, name, f"v2 hostile identity round-trip failed: {exc.code}")
        digest = entity_identity_digest(hostile_type, hostile_id)
        raw = json.loads(path.read_text(encoding="utf-8"))
        stored = (
            root / "entities" / ENTITY_STORE_DIRECTORY / str(raw["_v"])
            / digest[:2] / f"{digest}.json"
        )
        if (
            reopened.get(hostile_type, hostile_id).data != {"value": 1}
            or not stored.is_file()
            or raw.get("entity_storage", {}).get("schema") != "ze.entity-files.v2"
        ):
            return _fail(gate_id, name, "v2 identity mapping or marker is inconsistent")

        # A conservative legacy 0644 tree remains readable and is tightened on
        # its next save; this is the compatibility promise for existing projects.
        legacy_root = root / "legacy"
        legacy_root.mkdir()
        legacy_path = legacy_root / "document.json"
        legacy_doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
        legacy_entity = legacy_doc.add(Entity(type="card", id="row", data={"v": 1}))
        legacy_doc.save(legacy_path)
        raw = json.loads(legacy_path.read_text(encoding="utf-8"))
        del raw["entity_storage"]
        legacy_path.write_text(json.dumps(raw), encoding="utf-8")
        legacy_path.chmod(0o644)
        legacy_file = legacy_root / "entities" / "card" / "row.json"
        legacy_file.parent.mkdir()
        legacy_file.write_text(json.dumps(legacy_entity.to_dict()), encoding="utf-8")
        legacy_file.chmod(0o644)
        try:
            migrated = Document.open(legacy_path)
            migrated.save(legacy_path)
        except ZeError as exc:
            return _fail(gate_id, name, f"safe legacy migration failed: {exc.code}")
        if legacy_file.exists() or os.stat(legacy_path).st_mode & 0o077:
            return _fail(gate_id, name, "legacy layout was not removed and tightened")

        # A symlink encountered by pre-save audit must neither be followed nor
        # alter the authoritative document head.
        sentinel = root / "sentinel"
        sentinel.write_text("outside", encoding="utf-8")
        unsafe_entry = legacy_root / "entities" / "escape"
        unsafe_entry.symlink_to(sentinel)
        before = legacy_path.read_bytes()
        before_version = migrated.version
        try:
            migrated.save(legacy_path)
            return _fail(gate_id, name, "unsafe entity symlink was accepted")
        except ZeError as exc:
            if exc.code != "document_storage_path_unsafe":
                return _fail(gate_id, name, f"unsafe symlink wrong code: {exc.code}")
        if sentinel.read_text(encoding="utf-8") != "outside":
            return _fail(gate_id, name, "unsafe cleanup modified an external target")
        if legacy_path.read_bytes() != before or migrated.version != before_version:
            return _fail(gate_id, name, "pre-commit rejection switched document head")

        # Once document.json rename succeeds, a root fsync failure is UNKNOWN,
        # but visible disk and in-memory versions must remain aligned.
        unsafe_entry.unlink()
        real_fsync_directory = store_module._fsync_directory

        def fail_after_commit(descriptor: int, *, before_commit: bool) -> None:
            if not before_commit:
                raise EntityFileStoreError(
                    "document_durability_unknown",
                    "gate_root_fsync_failure",
                    committed=True,
                )
            real_fsync_directory(descriptor, before_commit=True)

        store_module._fsync_directory = fail_after_commit
        try:
            try:
                migrated.save(legacy_path)
                return _fail(gate_id, name, "post-rename fsync failure was acknowledged")
            except ZeError as exc:
                if exc.code != "document_durability_unknown":
                    return _fail(gate_id, name, f"post-rename wrong code: {exc.code}")
        finally:
            store_module._fsync_directory = real_fsync_directory
        visible_version = json.loads(legacy_path.read_text(encoding="utf-8"))["_v"]
        if migrated.version != visible_version:
            return _fail(gate_id, name, "visible and in-memory versions diverged")
    return _ok(gate_id, name)


def _document_stale_writer_child(
    document_path: str,
    value: int,
    channel: Any,
) -> None:
    """Spawn-safe writer used by the multi-process durable-head gate."""
    try:
        from document import Document
        from entity import Actor
        from entity_file_store import EntityFileStore

        document = Document.open(document_path)
        entity = document.get("item", "item-1")
        entity.update(
            {"value": value},
            expected_version=entity.version,
            actor=Actor(user_id="gate-writer-%s" % value),
        )
        channel.send(("ready", document.version))
        if channel.recv() != "commit":
            channel.send(("error", "gate_protocol_invalid"))
            return
        real_write_generation = EntityFileStore.write_generation

        def observed_generation_write(
            store: Any,
            version: int,
            payloads: dict[str, bytes],
        ) -> None:
            channel.send(("generation_write", value, version))
            real_write_generation(store, version, payloads)

        EntityFileStore.write_generation = observed_generation_write
        try:
            document.save(document_path)
        except BaseException as exc:
            channel.send(("rejected", getattr(exc, "code", type(exc).__name__)))
            return
        channel.send(("committed", document.version))
    except BaseException as exc:
        try:
            channel.send(("error", getattr(exc, "code", type(exc).__name__)))
        except BaseException:
            pass
    finally:
        channel.close()


def check_doc_08_multiprocess_durable_head_fence() -> GateResult:
    """Two stale writers must serialize; exactly one may advance the head."""
    import multiprocessing
    import tempfile

    from document import Document
    from entity import Entity

    gate_id = "GATE-DOC-08"
    name = "multiprocess_durable_head_fence"
    context = multiprocessing.get_context("spawn")
    with tempfile.TemporaryDirectory(prefix="ze-document-cas-gate-") as tmp:
        path = Path(tmp) / "document.json"
        seed = Document(
            schema_version="1.0.0",
            collaboration_mode="with_save",
            id="gate-document",
        )
        seed.add(Entity(type="item", id="item-1", data={"value": 0}))
        seed.save(path)
        initial_version = seed.version

        parents = []
        children = []
        processes = []
        try:
            for value in (1, 2):
                parent, child = context.Pipe(duplex=True)
                process = context.Process(
                    target=_document_stale_writer_child,
                    args=(str(path), value, child),
                )
                parents.append(parent)
                children.append(child)
                processes.append(process)
                process.start()
                child.close()

            for parent in parents:
                if not parent.poll(20.0):
                    return _fail(gate_id, name, "writer did not open the shared head")
                ready = parent.recv()
                if ready != ("ready", initial_version):
                    return _fail(gate_id, name, f"writer opened a divergent head: {ready!r}")
            for parent in parents:
                parent.send("commit")

            results = []
            generation_writes = []
            for parent in parents:
                while True:
                    if not parent.poll(20.0):
                        return _fail(gate_id, name, "writer did not finish its commit attempt")
                    message = parent.recv()
                    if message[0] == "generation_write":
                        generation_writes.append(message)
                        continue
                    results.append(message)
                    break
            for process in processes:
                process.join(20.0)
                if process.is_alive():
                    return _fail(gate_id, name, "writer process did not exit")
                if process.exitcode != 0:
                    return _fail(gate_id, name, f"writer process exited {process.exitcode}")
        finally:
            for process in processes:
                if process.is_alive():
                    process.terminate()
                    process.join(5.0)
            for parent in parents:
                parent.close()
            for child in children:
                try:
                    child.close()
                except OSError:
                    pass

        if sorted(results) != sorted((
            ("committed", initial_version + 1),
            ("rejected", "version_conflict"),
        )):
            return _fail(
                gate_id,
                name,
                f"expected one commit and one stale rejection, got {results!r}",
            )
        if len(generation_writes) != 1:
            return _fail(
                gate_id,
                name,
                f"stale loser reached generation write: {generation_writes!r}",
            )
        reopened = Document.open(path)
        if (
            reopened.version != initial_version + 1
            or reopened.get("item", "item-1").data.get("value") not in (1, 2)
        ):
            return _fail(gate_id, name, "durable head does not match the sole winner")
    return _ok(gate_id, name)


def _gate_ast_call_name(node: Any) -> str:
    """Return the terminal callable name for a small, syntax-only audit."""
    import ast

    if not isinstance(node, ast.Call):
        return ""
    if isinstance(node.func, ast.Name):
        return node.func.id
    if isinstance(node.func, ast.Attribute):
        return node.func.attr
    return ""


def _gate_ast_functions(tree: Any, name: str) -> list[Any]:
    import ast

    return [
        node for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == name
    ]


def _gate_ast_calls(function: Any) -> set[str]:
    import ast

    return {
        _gate_ast_call_name(node)
        for node in ast.walk(function)
        if isinstance(node, ast.Call)
    }


def _find_private_topology_rewrite_uses(
    source: str,
    *,
    filename: str = "<source>",
) -> list[str]:
    """Find imports/references that could bypass the staging-only wrapper."""
    import ast

    sensitive = {
        "_TOPOLOGY_STAGING_METADATA_CAPABILITY",
        "_rewrite_document_metadata_for_topology_staging",
    }
    tree = ast.parse(source, filename=filename)
    uses: list[str] = []
    for node in ast.walk(tree):
        member = ""
        if isinstance(node, ast.ImportFrom) and (
            node.module == "document"
            and any(alias.name in sensitive or alias.name == "*" for alias in node.names)
        ):
            member = "document import"
        elif isinstance(node, ast.Name) and node.id in sensitive:
            member = node.id
        elif isinstance(node, ast.Attribute) and node.attr in sensitive:
            member = node.attr
        elif isinstance(node, ast.Constant) and node.value in sensitive:
            member = str(node.value)
        if member:
            uses.append(f"{filename}:{getattr(node, 'lineno', 0)}:{member}")
    return sorted(set(uses))


def _find_private_legacy_scan_uses(
    source: str,
    *,
    filename: str = "<source>",
) -> list[str]:
    """Find production access to the unpublished legacy scan Document seam."""
    import ast

    sensitive = {
        "_LEGACY_SCAN_DOCUMENT_CAPABILITY",
        "_open_document_for_legacy_scan",
    }
    tree = ast.parse(source, filename=filename)
    uses: list[str] = []
    for node in ast.walk(tree):
        member = ""
        if isinstance(node, ast.ImportFrom) and (
            node.module == "document"
            and any(alias.name in sensitive or alias.name == "*" for alias in node.names)
        ):
            member = "document import"
        elif isinstance(node, ast.Name) and node.id in sensitive:
            member = node.id
        elif isinstance(node, ast.Attribute) and node.attr in sensitive:
            member = node.attr
        elif isinstance(node, ast.Constant) and node.value in sensitive:
            member = str(node.value)
        if member:
            uses.append(f"{filename}:{getattr(node, 'lineno', 0)}:{member}")
    return sorted(set(uses))


_NON_SOURCE_PYTHON_DIRS = frozenset({
    ".git", ".venv", "venv", ".tox", ".nox", "node_modules",
    "__pycache__", ".pytest_cache", ".mypy_cache", ".ruff_cache",
    ".data", "dist", "build",
})


def _iter_auditable_python_sources(skill_root: Path):
    """Yield repository-owned Python without entering runtime/dependency trees.

    DOC-09 audits production source authority, not the active interpreter's
    installed packages.  Pruning while walking is both faster and prevents a
    host Python (for example 3.9) from parsing syntax installed into a target
    ``.venv`` by another Python (for example 3.13).
    """
    import os

    root = Path(skill_root).resolve()
    for directory, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(
            name for name in dirnames if name not in _NON_SOURCE_PYTHON_DIRS
        )
        base = Path(directory)
        for filename in sorted(filenames):
            if filename.endswith(".py"):
                yield base / filename


def check_doc_09_validated_head_authority(root: Path | None = None) -> GateResult:
    """Metadata views and every durable-head path must share one strict parser."""
    import ast
    import json
    import tempfile

    from document import (
        Document,
        DocumentMetadata,
        _rewrite_document_metadata_for_topology_staging,
        open_document_head,
        read_document_metadata,
    )
    from entity import ZeError
    from entity_file_store import EntityFileStore, EntityFileStoreError

    gate_id = "GATE-DOC-09"
    name = "validated_document_head_authority"
    skill_root = Path(root) if root is not None else _CORE.parent
    source_path = (
        skill_root / "01-core" / "01-data-structure" / "01-document"
        / "document.py"
    )
    try:
        tree = ast.parse(
            source_path.read_text(encoding="utf-8"), filename=str(source_path),
        )
    except (OSError, SyntaxError) as exc:
        return _fail(gate_id, name, f"document authority source is invalid: {exc}")

    # The capability is an internal architecture boundary, not an in-process
    # security sandbox.  Keep imports/references out of every production module
    # except the domain definition and the topology wrapper, so ordinary
    # server/bootstrap code cannot accidentally turn it into a live edit API.
    allowed = {
        source_path.resolve(),
        (skill_root / "sdk" / "project_topology.py").resolve(),
    }
    escapes: list[str] = []
    for candidate in _iter_auditable_python_sources(skill_root):
        relative = candidate.relative_to(skill_root)
        if candidate.resolve() in allowed:
            continue
        if (
            candidate.name.startswith("test_")
            or candidate.name.endswith("_test.py")
            or "tests" in relative.parts
            or "_protocol" in relative.parts
        ):
            continue
        try:
            uses = _find_private_topology_rewrite_uses(
                candidate.read_text(encoding="utf-8"), filename=str(relative),
            )
        except (OSError, SyntaxError) as exc:
            return _fail(gate_id, name, f"could not audit {relative}: {exc}")
        escapes.extend(uses)
    if escapes:
        return _fail(
            gate_id,
            name,
            "private topology metadata authority escaped its sole wrapper",
            {"uses": escapes},
        )

    legacy_import_path = (skill_root / "sdk" / "legacy_import.py").resolve()
    scan_escapes: list[str] = []
    importer_scan_uses: list[str] = []
    for candidate in _iter_auditable_python_sources(skill_root):
        relative = candidate.relative_to(skill_root)
        if candidate.resolve() == source_path.resolve():
            continue
        if (
            candidate.name.startswith("test_")
            or candidate.name.endswith("_test.py")
            or "tests" in relative.parts
            or "_protocol" in relative.parts
        ):
            continue
        try:
            uses = _find_private_legacy_scan_uses(
                candidate.read_text(encoding="utf-8"), filename=str(relative),
            )
        except (OSError, SyntaxError) as exc:
            return _fail(gate_id, name, f"could not audit {relative}: {exc}")
        if candidate.resolve() == legacy_import_path:
            importer_scan_uses.extend(uses)
        else:
            scan_escapes.extend(uses)
    if scan_escapes:
        return _fail(
            gate_id,
            name,
            "legacy Document scan authority escaped its sole importer",
            {"uses": scan_escapes},
        )
    if not importer_scan_uses:
        return _fail(
            gate_id,
            name,
            "legacy importer does not consume the sealed Document scan authority",
        )

    # This is deliberately structural rather than a text search.  It proves
    # that full opens, save CAS, metadata reads and staging rewrites converge on
    # the same semantic parser, while the public convenience reader obtains a
    # lock-scoped head instead of opening the file itself.
    required_calls = {
        "open": "_parse_document_head",
        "save": "_parse_document_head",
        "open_document_head": "_parse_document_head",
        "read_document_metadata": "open_document_head",
        "_rewrite_document_metadata_for_topology_staging": "_parse_document_head",
    }
    for function_name, required_call in required_calls.items():
        candidates = _gate_ast_functions(tree, function_name)
        if not candidates or not any(
            required_call in _gate_ast_calls(candidate)
            for candidate in candidates
        ):
            return _fail(
                gate_id,
                name,
                f"{function_name} does not consume {required_call}",
            )

    scanner_functions = _gate_ast_functions(
        tree, "_open_document_for_legacy_scan",
    )
    loader_functions = _gate_ast_functions(
        tree, "_load_persisted_document_from_locked_store",
    )
    open_functions = _gate_ast_functions(tree, "open")
    if (
        not scanner_functions
        or not any(
            {
                "EntityFileStore", "_parse_document_head",
                "_load_persisted_document_from_locked_store",
            }.issubset(_gate_ast_calls(function))
            for function in scanner_functions
        )
        or not loader_functions
        or not any(
            {"read_v2_entity", "read_legacy_entity", "_restore_persisted_document"}
            .issubset(_gate_ast_calls(function))
            for function in loader_functions
        )
        or not any(
            "_load_persisted_document_from_locked_store" in _gate_ast_calls(function)
            for function in open_functions
        )
    ):
        return _fail(
            gate_id,
            name,
            "public open and dormant scanner do not share one locked-store loader",
        )

    rewrite_functions = _gate_ast_functions(
        tree, "_rewrite_document_metadata_for_topology_staging",
    )
    rewrite_pins_store = any(
        isinstance(node, ast.Call)
        and _gate_ast_call_name(node) == "EntityFileStore"
        and any(
            keyword.arg == "_expected_root_identity"
            and isinstance(keyword.value, ast.Name)
            and keyword.value.id == "_expected_root_identity"
            for keyword in node.keywords
        )
        for function in rewrite_functions
        for node in ast.walk(function)
    )
    store_source_path = source_path.with_name("entity_file_store.py")
    try:
        store_tree = ast.parse(
            store_source_path.read_text(encoding="utf-8"),
            filename=str(store_source_path),
        )
    except (OSError, SyntaxError) as exc:
        return _fail(gate_id, name, f"entity store authority source is invalid: {exc}")
    store_initializers = [
        function for function in _gate_ast_functions(store_tree, "__init__")
        if "_open_root" in _gate_ast_calls(function)
    ]
    store_identity_constants = {
        node.value
        for function in store_initializers
        for node in ast.walk(function)
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    }
    store_identity_members = {
        node.attr
        for function in store_initializers
        for node in ast.walk(function)
        if isinstance(node, ast.Attribute)
    }
    if (
        not rewrite_pins_store
        or not store_initializers
        or not any("_fstat" in _gate_ast_calls(fn) for fn in store_initializers)
        or not {"st_dev", "st_ino"}.issubset(store_identity_members)
        or "project_directory_identity_mismatch" not in store_identity_constants
    ):
        return _fail(
            gate_id,
            name,
            "staging root identity pin does not reach the opened EntityFileStore root",
        )

    with tempfile.TemporaryDirectory(prefix="ze-document-head-gate-") as tmp:
        path = Path(tmp) / "document.json"
        document = Document(
            schema_version="1.0.0",
            collaboration_mode="with_save",
            id="head-authority",
            name="Head authority",
            config={"nested": {"value": 1}},
            acl={"owner": "owner", "collaborators": ["member"]},
            save_policy="auto_commit",
        )
        document.save(path)
        root_info = path.parent.stat()
        try:
            unexpected_store = EntityFileStore(
                path,
                create_parent=False,
                _expected_root_identity=(root_info.st_dev, root_info.st_ino + 1),
            )
        except EntityFileStoreError as exc:
            if (
                exc.code != "document_storage_path_unsafe"
                or exc.reason != "project_directory_identity_mismatch"
            ):
                return _fail(
                    gate_id,
                    name,
                    f"root identity mismatch returned {exc.code}/{exc.reason}",
                )
        else:
            unexpected_store.close()
            return _fail(gate_id, name, "EntityFileStore accepted a different root inode")
        metadata = read_document_metadata(path)
        reopened = Document.open(path)
        if (
            metadata.id != reopened.id
            or metadata.version != reopened.version
            or metadata.config != reopened.config
            or metadata.acl != reopened.acl
        ):
            return _fail(gate_id, name, "metadata view disagrees with full Document.open")

        with open_document_head(path) as head:
            if head is None or head.payload != path.read_bytes():
                return _fail(gate_id, name, "lock-scoped head lost its exact payload")
            detached = head.envelope
            detached["config"]["nested"]["value"] = 7
        config_view = metadata.config
        config_view["nested"]["value"] = 9
        if read_document_metadata(path).config != {"nested": {"value": 1}}:
            return _fail(gate_id, name, "nested metadata leaked a mutable alias")
        fragment_names = (
            "_data_schema_fragment",
            "_config_fragment",
            "_acl_fragment",
            "_collections_fragment",
            "_entity_storage_fragment",
            "_read_only_sources_fragment",
        )
        if hasattr(metadata, "_payload") or any(
            type(getattr(metadata, member, None)) is not bytes
            for member in fragment_names
        ):
            return _fail(
                gate_id,
                name,
                "metadata carrier retained a full head or lost compact fragments",
            )

        try:
            DocumentMetadata(
                id=metadata.id,
                name=metadata.name,
                schema=metadata.schema,
                schema_version=metadata.schema_version,
                collaboration_mode=metadata.collaboration_mode,
                save_policy=metadata.save_policy,
                created_at=metadata.created_at,
                updated_at=metadata.updated_at,
                version=metadata.version,
                storage_version=metadata.storage_version,
                _data_schema_fragment=metadata._data_schema_fragment,
                _config_fragment=metadata._config_fragment,
                _acl_fragment=metadata._acl_fragment,
                _collections_fragment=metadata._collections_fragment,
                _entity_storage_fragment=metadata._entity_storage_fragment,
                _read_only_sources_fragment=metadata._read_only_sources_fragment,
                _seal=object(),
            )
            return _fail(gate_id, name, "validated metadata carrier was forgeable")
        except TypeError as exc:
            if str(exc) != "DocumentMetadata requires validated head authority":
                return _fail(
                    gate_id,
                    name,
                    f"carrier forgery test missed the seal boundary: {exc}",
                )

        before = path.read_bytes()
        try:
            _rewrite_document_metadata_for_topology_staging(
                path,
                expected_version=metadata.version,
                name="forbidden live rewrite",
                _expected_root_identity=(0, 0),
            )
            return _fail(gate_id, name, "metadata rewrite accepted no staging authority")
        except ZeError as exc:
            if exc.code != "topology_metadata_rewrite_forbidden":
                return _fail(gate_id, name, f"rewrite returned wrong code: {exc.code}")
        if path.read_bytes() != before:
            return _fail(gate_id, name, "forbidden metadata rewrite changed the head")

        # The metadata-only reader must reject exactly the kind of malformed
        # durable field that the full loader rejects; it may not maintain a
        # weaker, authorization-specific JSON interpretation.
        corrupt = json.loads(before.decode("utf-8"))
        corrupt["config"] = []
        path.write_text(json.dumps(corrupt), encoding="utf-8")
        failures: list[str] = []
        for reader in (read_document_metadata, Document.open):
            try:
                reader(path)
                failures.append("accepted")
            except ZeError as exc:
                failures.append(exc.code)
        if failures != ["project_recovery_required", "project_recovery_required"]:
            return _fail(
                gate_id,
                name,
                f"metadata/full readers diverged on malformed head: {failures!r}",
            )

        # Legacy collection identities are durable path components, including
        # types with empty buckets.  The zero-Entity metadata seam must reject
        # them in the shared parser instead of deferring the decision to
        # Document.open's first read_legacy_entity call.
        legacy_cases = (
            ({"bad/type": []}, "legacy_component_invalid"),
            ({".": []}, "legacy_component_invalid"),
            ({"bad\x00type": []}, "legacy_component_invalid"),
            ({".ze-store-v2": []}, "legacy_type_reserved"),
            ({"card": ["bad/id"]}, "legacy_component_invalid"),
            ({"card": [".."]}, "legacy_component_invalid"),
            ({"card": ["bad\x00id"]}, "legacy_component_invalid"),
        )
        for bad_collections, expected_reason in legacy_cases:
            legacy = json.loads(before.decode("utf-8"))
            legacy.pop("entity_storage", None)
            legacy["collections"] = bad_collections
            path.write_text(
                json.dumps(legacy, ensure_ascii=False, allow_nan=False),
                encoding="utf-8",
            )
            diagnoses = []
            for reader in (read_document_metadata, Document.open):
                try:
                    reader(path)
                    diagnoses.append(("accepted", ""))
                except ZeError as exc:
                    diagnoses.append((exc.code, exc.context.get("reason")))
            expected = (
                "document_storage_layout_invalid",
                expected_reason,
            )
            if diagnoses != [expected, expected]:
                return _fail(
                    gate_id,
                    name,
                    "metadata/full readers diverged on legacy collection path: "
                    f"{diagnoses!r}",
                )
    return _ok(gate_id, name, "one parser + detached sealed views + staging-only rewrite")


def check_doc_10_atomic_document_commit_candidate() -> GateResult:
    """The DB handoff may consume only one opaque, live-session head advance."""
    gate_id = "GATE-DOC-10"
    name = "atomic_document_commit_candidate"
    try:
        import copy

        import document as document_module
        import sdk as public_sdk
        from document import Document
        from entity import Actor, Entity, ZeError

        private_names = {
            "_ATOMIC_DOCUMENT_COMMIT_CAPABILITY",
            "_DocumentCommitCandidate",
            "_VerifiedDocumentCommitCandidate",
            "_verify_atomic_document_commit_candidate",
        }
        if private_names.intersection(public_sdk.__all__):
            raise RuntimeError("atomic Document candidate leaked into sdk.__all__")

        document = Document(
            id="gate-atomic-document",
            schema_version="1.0.0",
            collaboration_mode="with_save",
            save_policy="auto_commit",
        )
        entity = Entity(type="card", id="card-1", data={"title": "before"})
        document.add(entity)
        before_version = document.version
        before_updated_at = document.updated_at
        before_title = entity.data["title"]

        ordinary = document.begin_mutation_session()
        try:
            ordinary._prepare_atomic_commit_candidate(
                before_version,
                _capability=document_module._ATOMIC_DOCUMENT_COMMIT_CAPABILITY,
            )
            raise RuntimeError("non-exclusive session issued an atomic candidate")
        except ZeError as exc:
            if exc.code != "mutation_session_exclusive_required":
                raise RuntimeError("non-exclusive candidate returned wrong diagnosis")
        finally:
            ordinary.rollback()

        session = document.begin_mutation_session(exclusive=True)
        entity.update(
            {"title": "candidate"},
            expected_version=entity.version,
            actor=Actor(user_id="gate-user"),
        )
        try:
            session._prepare_atomic_commit_candidate(before_version)
            raise RuntimeError("candidate issuer accepted a missing capability")
        except ZeError as exc:
            if exc.code != "document_atomic_commit_forbidden":
                raise RuntimeError("missing capability returned wrong diagnosis")

        candidate = session._prepare_atomic_commit_candidate(
            before_version,
            _capability=document_module._ATOMIC_DOCUMENT_COMMIT_CAPABILITY,
        )
        verified = document_module._verify_atomic_document_commit_candidate(
            candidate,
            document,
            session,
            _capability=document_module._ATOMIC_DOCUMENT_COMMIT_CAPABILITY,
        )
        if (
            hasattr(candidate, "__dict__")
            or verified.document_id != document.id
            or verified.before_version != before_version
            or verified.document_version != before_version + 1
            or verified.document_version != document.version
            or verified.updated_at != document.updated_at
        ):
            raise RuntimeError("candidate lost its exact opaque head binding")
        try:
            copy.copy(candidate)
            raise RuntimeError("candidate became copyable")
        except TypeError:
            pass
        try:
            session._prepare_atomic_commit_candidate(
                document.version,
                _capability=document_module._ATOMIC_DOCUMENT_COMMIT_CAPABILITY,
            )
            raise RuntimeError("one session issued two candidates")
        except ZeError as exc:
            if exc.code != "document_commit_candidate_already_issued":
                raise RuntimeError("duplicate candidate returned wrong diagnosis")

        # A failed SQL attempt must retain exact rollback authority, including
        # object identity, business data, version and timestamp.
        session.rollback()
        if (
            document.version != before_version
            or document.updated_at != before_updated_at
            or document.get("card", "card-1") is not entity
            or entity.data["title"] != before_title
        ):
            raise RuntimeError("candidate rollback did not restore the exact graph")
        try:
            document_module._verify_atomic_document_commit_candidate(
                candidate,
                document,
                session,
                _capability=document_module._ATOMIC_DOCUMENT_COMMIT_CAPABILITY,
            )
            raise RuntimeError("closed candidate remained verifiable")
        except ZeError as exc:
            if exc.code != "document_commit_candidate_invalid":
                raise RuntimeError("closed candidate returned wrong diagnosis")
    except BaseException as exc:
        return _fail(
            gate_id,
            name,
            "atomic Document candidate probe failed: %s:%s"
            % (getattr(exc, "code", type(exc).__name__), str(exc)),
        )
    return _ok(
        gate_id,
        name,
        "opaque exclusive-session candidate + exact one-shot advance + exact rollback",
    )


# ---- ENT ----

def check_ent_01_cas_protocol() -> GateResult:
    """update 不匹配 expected_version 抛 cas_version_mismatch."""
    from entity import Entity, Actor, ZeError
    e = Entity(type="t", data={"x": 1})
    try:
        e.update({"x": 2}, expected_version=99, actor=Actor(user_id="u1"))
        return _fail("GATE-ENT-01", "entity_cas_protocol", "no exception thrown")
    except ZeError as exc:
        if exc.code != "cas_version_mismatch":
            return _fail("GATE-ENT-01", "entity_cas_protocol", f"wrong code: {exc.code}")
    return _ok("GATE-ENT-01", "entity_cas_protocol")


def check_ent_02_read_only_protection() -> GateResult:
    """read_only entity 写抛 read_only_violation."""
    from entity import Entity, Actor, ZeError
    e = Entity(type="t", data={}, read_only=True)
    for op_fn, args in [
        ("update", ({"x": 1},)),
        ("delete", ()),
        ("restore", ()),
    ]:
        try:
            method = getattr(e, op_fn)
            method(*args, expected_version=1, actor=Actor(user_id="u1"))
            return _fail("GATE-ENT-02", "entity_read_only_protection",
                         f"{op_fn} on read_only entity should raise")
        except ZeError as exc:
            if exc.code != "read_only_violation":
                return _fail("GATE-ENT-02", "entity_read_only_protection",
                             f"{op_fn} raised wrong code: {exc.code}")
    return _ok("GATE-ENT-02", "entity_read_only_protection")


def check_ent_03_soft_deleted_no_update() -> GateResult:
    """软删后 update 抛 entity_soft_deleted; restore 仍可."""
    from entity import Entity, Actor, ZeError
    e = Entity(type="t", data={})
    actor = Actor(user_id="u1")
    e.delete(expected_version=1, actor=actor)
    try:
        e.update({"x": 1}, expected_version=e.version, actor=actor)
        return _fail("GATE-ENT-03", "entity_soft_deleted_no_update",
                     "update on soft-deleted should raise")
    except ZeError as exc:
        if exc.code != "entity_soft_deleted":
            return _fail("GATE-ENT-03", "entity_soft_deleted_no_update",
                         f"wrong code: {exc.code}")
    # restore 应该工作
    e.restore(expected_version=e.version, actor=actor)
    if e.deleted:
        return _fail("GATE-ENT-03", "entity_soft_deleted_no_update",
                     "restore failed to undelete")
    return _ok("GATE-ENT-03", "entity_soft_deleted_no_update")


# ---- AST ----

def check_ast_01_checksum_integrity() -> GateResult:
    """blob 篡改后 get 抛 asset_corrupted."""
    import tempfile
    from asset import AssetStore
    from entity import ZeError
    with tempfile.TemporaryDirectory() as td:
        store = AssetStore(td)
        ref = store.put(b"hello", ext=".txt")
        # 篡改 blob
        blob_path = Path(td) / "blobs" / ref.sha256[:2] / f"{ref.sha256}.txt"
        blob_path.write_bytes(b"TAMPERED")
        try:
            store.get(ref)
            return _fail("GATE-AST-01", "asset_checksum_integrity",
                         "tampered blob should raise asset_corrupted")
        except ZeError as e:
            if e.code != "asset_corrupted":
                return _fail("GATE-AST-01", "asset_checksum_integrity",
                             f"wrong code: {e.code}")
    return _ok("GATE-AST-01", "asset_checksum_integrity")


def check_ast_02_document_reachability_gc() -> GateResult:
    """GC 以完整 Document 可达性为准；无 doc fail-closed，stale refs 不能误导。"""
    import tempfile
    from asset import AssetStore
    from document import Document
    from entity import Entity, ZeError

    name = "asset_document_reachability_gc"
    with tempfile.TemporaryDirectory() as td:
        store = AssetStore(td)
        keep = store.put(b"keep")             # stale zero,但 Document 真引用两槽
        drop = store.put(b"drop")
        store.add_ref(drop)                    # stale positive,但 Document 不可达
        doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
        doc.add(Entity(type="obj", id="e1", data={
            "asset": keep.to_dict(), "thumbnail": keep.to_dict(),
        }))

        try:
            store.gc()
            return _fail("GATE-AST-02", name, "gc without Document did not fail closed")
        except ZeError as exc:
            if exc.code != "asset_reachability_required":
                return _fail("GATE-AST-02", name, f"wrong no-doc code: {exc.code}")
        if not store.has(keep) or not store.has(drop):
            return _fail("GATE-AST-02", name, "no-doc gc removed a local blob")

        removed = store.gc(doc)
        if removed != [drop.sha256]:
            return _fail("GATE-AST-02", name, f"wrong unreachable set: {removed}")
        if not store.has(keep) or store.ref_count(keep) != 2:
            return _fail("GATE-AST-02", name, "reachable multiset was not reconciled")
    return _ok("GATE-AST-02", name)


def check_ast_04_release_idempotent_at_zero() -> GateResult:
    """refs=0 再 release 仍 0."""
    import tempfile
    from asset import AssetStore
    with tempfile.TemporaryDirectory() as td:
        store = AssetStore(td)
        ref = store.put(b"x")
        for _ in range(3):
            v = store.release(ref)
            if v != 0:
                return _fail("GATE-AST-04", "asset_release_idempotent_at_zero",
                             f"release at 0 returned {v}, expected 0")
    return _ok("GATE-AST-04", "asset_release_idempotent_at_zero")


def check_ast_05_shared_pool_fallback() -> GateResult:
    """共享池 fallback 不变量(P3):读委托共享、写留本地、is_local 区分、promote 复制。"""
    import tempfile
    from asset import AssetStore
    from entity import ZeError
    name = "asset_shared_pool_fallback"
    with tempfile.TemporaryDirectory() as td:
        shared = AssetStore(Path(td) / "shared")
        local = AssetStore(Path(td) / "p", fallback=shared)
        sref = shared.put(b"shared")
        # 读委托:本地非本地、但可经 fallback 读
        if local.is_local(sref) or not local.has(sref) or local.get(sref) != b"shared":
            return _fail("GATE-AST-05", name, "fallback read delegation broken")
        # 写留本地:put 不漏进共享、引用计数不串台
        lref = local.put(b"localonly")
        if not local.is_local(lref) or shared.has(lref):
            return _fail("GATE-AST-05", name, "local write leaked into shared pool")
        local.add_ref(lref)
        if shared.ref_count(lref) != 0:
            return _fail("GATE-AST-05", name, "ref count crossed into shared pool")
        # promote 复制进共享
        out = local.promote(lref)
        if out.sha256 != lref.sha256 or not shared.has(lref):
            return _fail("GATE-AST-05", name, "promote did not copy into shared pool")
        # 无 fallback → promote 报错
        try:
            AssetStore(Path(td) / "solo").promote(lref)
            return _fail("GATE-AST-05", name, "promote without fallback did not raise")
        except ZeError as e:
            if e.code != "asset_no_shared_pool":
                return _fail("GATE-AST-05", name, f"wrong code: {e.code}")
    return _ok("GATE-AST-05", name)


