def check_op_02_hash_chain_intact() -> GateResult:
    """OpLog 全程 verify_chain 应 True; 篡改任何 entry 应 False."""
    from operation import OpLog, Patch, new_operation
    log = OpLog()
    for i in range(3):
        op = new_operation(
            command_id="x", source="user", actor={"user_id": "u1"},
            patches=[Patch("t", str(i), "k", "set", None, i)],
            reverse_patches=[Patch("t", str(i), "k", "set", i, None)],
        )
        log.append(op)
    if not log.verify_chain():
        return _fail("GATE-OP-02", "oplog_hash_chain_intact", "clean chain failed verify")
    # 篡改 entry 0
    log._entries[0]["op"]["command_id"] = "TAMPERED"
    if log.verify_chain():
        return _fail("GATE-OP-02", "oplog_hash_chain_intact",
                     "tampered chain still passes verify")
    return _ok("GATE-OP-02", "oplog_hash_chain_intact")


