def check_op_07_truncated_tail_durable_repair() -> GateResult:
    """An uncommitted tail must be physically removed before durable append."""
    import tempfile

    from entity import ZeError
    from operation import OpLog, new_operation

    gate_id = "GATE-OP-07"
    name = "oplog_truncated_tail_durable_repair"

    def make_op():
        return new_operation(
            command_id="gate.oplog.append",
            source="system",
            actor={"user_id": "gate"},
            patches=[],
            reverse_patches=[],
        )

    try:
        with tempfile.TemporaryDirectory(prefix="ze-oplog-tail-gate-") as tmp:
            path = Path(tmp) / "oplog.ndjson"
            live = OpLog(path)
            first = live.append(make_op())
            with open(path, "ab") as stream:
                stream.write(b'{"crashed":"partial')

            second = live.append(make_op())
            if (
                second["prev_hash"] != first["self_hash"]
                or not live._truncated_tail_dropped
                or not path.read_bytes().endswith(b"\n")
            ):
                return _fail(gate_id, name, "live append did not durably repair tail")

            first_reload = OpLog(path)
            second_reload = OpLog(path)
            if (
                len(first_reload) != 2
                or len(second_reload) != 2
                or not first_reload.verify_chain()
                or not second_reload.verify_chain()
            ):
                return _fail(gate_id, name, "fresh reload lost a post-repair operation")

            with open(path, "ab") as stream:
                stream.write(b"{terminated-corruption}\n")
            try:
                OpLog(path)
                return _fail(gate_id, name, "LF-terminated corruption was soft-dropped")
            except ZeError as exc:
                if exc.code != "oplog_corrupt":
                    return _fail(gate_id, name, "wrong terminated-corruption error")
    except BaseException as exc:
        return _fail(
            gate_id,
            name,
            "OpLog tail repair probe failed: %s:%s"
            % (getattr(exc, "code", type(exc).__name__), str(exc)),
        )
    return _ok(gate_id, name, "truncate+fsync+append survived two fresh reloads")


def check_op_08_strict_storage_boundary() -> GateResult:
    """OpLog path, JSON and capacity boundaries fail closed without disclosure."""
    import os
    import stat
    import tempfile

    import operation as operation_module
    from entity import ZeError
    from operation import OpLog, ZERO_HASH, new_operation

    gate_id = "GATE-OP-08"
    name = "oplog_strict_storage_boundary"

    def make_op():
        return new_operation(
            command_id="gate.oplog.boundary",
            source="system",
            actor={"user_id": "gate"},
            patches=[],
            reverse_patches=[],
        )

    def expect_safe_error(call, code: str, *, secret: str = "") -> str | None:
        try:
            call()
        except ZeError as exc:
            if exc.code != code:
                return f"expected {code}, got {exc.code}"
            exposed = f"{exc.message} {exc.context} {exc}"
            if exc.context or exc.__cause__ is not None:
                return f"{code} retained context or cause"
            if secret and secret in exposed:
                return f"{code} disclosed protected input"
            return None
        except BaseException as exc:
            return f"raw exception escaped: {type(exc).__name__}"
        return f"{code} boundary was accepted"

    original_record_limit = operation_module._MAX_OPLOG_RECORD_BYTES
    original_total_limit = operation_module._MAX_OPLOG_BYTES
    try:
        with tempfile.TemporaryDirectory(prefix="ze-oplog-boundary-gate-") as tmp:
            root = Path(tmp)
            private = root / "private.ndjson"
            log = OpLog(private)
            log.append(make_op())
            if stat.S_IMODE(private.stat().st_mode) != 0o600:
                return _fail(gate_id, name, "new oplog was not owner-only")

            target = root / "target.ndjson"
            target.write_bytes(b"sentinel")
            symlink = root / "secret-symlink.ndjson"
            symlink.symlink_to(target)
            problem = expect_safe_error(
                lambda: OpLog(symlink), "oplog_path_unsafe", secret="secret-symlink",
            )
            if problem or target.read_bytes() != b"sentinel":
                return _fail(gate_id, name, problem or "symlink target was changed")

            hard_target = root / "hard-target.ndjson"
            hard_target.write_bytes(b"")
            hardlink = root / "hardlink.ndjson"
            os.link(hard_target, hardlink)
            problem = expect_safe_error(lambda: OpLog(hardlink), "oplog_path_unsafe")
            if problem:
                return _fail(gate_id, name, problem)

            real_parent = root / "real-parent"
            real_parent.mkdir()
            linked_parent = root / "linked-parent"
            linked_parent.symlink_to(real_parent, target_is_directory=True)
            problem = expect_safe_error(
                lambda: OpLog(linked_parent / "oplog.ndjson"),
                "oplog_path_unsafe",
            )
            if problem or (real_parent / "oplog.ndjson").exists():
                return _fail(gate_id, name, problem or "parent symlink was followed")

            corrupt = root / "corrupt.ndjson"
            corrupt.write_bytes(
                b'{"op":{"secret":"first","secret":"second"},'
                b'"prev_hash":"x","self_hash":"y"}\n'
            )
            problem = expect_safe_error(
                lambda: OpLog(corrupt), "oplog_corrupt", secret="first",
            )
            if problem:
                return _fail(gate_id, name, problem)

            nonfinite = root / "nonfinite.ndjson"
            nonfinite.write_bytes(
                b'{"op":{"value":NaN},"prev_hash":"x","self_hash":"y"}\n'
            )
            problem = expect_safe_error(lambda: OpLog(nonfinite), "oplog_corrupt")
            if problem:
                return _fail(gate_id, name, problem)

            golden_body = {"a": 1, "b": "中文", "nested": {"ok": True}}
            if OpLog._hash(ZERO_HASH, golden_body) != (
                "2ebd3e831a0577dd639563705bec90842d1a045ff9cff6c7d95093148b7520eb"
            ):
                return _fail(gate_id, name, "finite historical hash format changed")

            actor = {"nested": {"role": "user"}}
            mutable_op = new_operation(
                command_id="gate.oplog.freeze",
                source="system",
                actor=actor,
                patches=[],
                reverse_patches=[],
            )
            real_dumps = operation_module.json.dumps
            dump_calls = 0

            def mutate_after_first_dump(*args, **kwargs):
                nonlocal dump_calls
                result = real_dumps(*args, **kwargs)
                dump_calls += 1
                if dump_calls == 1:
                    actor["nested"]["role"] = "tampered"
                return result

            frozen_path = root / "frozen.ndjson"
            frozen_log = OpLog(frozen_path)
            operation_module.json.dumps = mutate_after_first_dump
            try:
                returned = frozen_log.append(mutable_op)
            finally:
                operation_module.json.dumps = real_dumps
            returned["op"]["actor"]["nested"]["role"] = "returned-tamper"
            stored_role = frozen_log.entries()[0]["op"]["actor"]["nested"]["role"]
            if (
                dump_calls < 3
                or stored_role != "user"
                or not frozen_log.verify_chain()
                or not OpLog(frozen_path).verify_chain()
            ):
                return _fail(gate_id, name, "caller mutation broke frozen hash chain")

            operation_module._MAX_OPLOG_RECORD_BYTES = 64
            record_path = root / "record-limit.ndjson"
            record_log = OpLog(record_path)
            problem = expect_safe_error(
                lambda: record_log.append(make_op()), "oplog_entry_invalid",
            )
            record_bytes = record_path.read_bytes() if record_path.exists() else b""
            if problem or len(record_log) or record_bytes != b"":
                return _fail(gate_id, name, problem or "record limit published state")

            operation_module._MAX_OPLOG_RECORD_BYTES = original_record_limit
            total_path = root / "total-limit.ndjson"
            total_log = OpLog(total_path)
            total_log.append(make_op())
            before = total_path.read_bytes()
            operation_module._MAX_OPLOG_BYTES = len(before) + 1
            problem = expect_safe_error(
                lambda: total_log.append(make_op()), "oplog_limit_exceeded",
            )
            if problem or total_path.read_bytes() != before or len(total_log) != 1:
                return _fail(gate_id, name, problem or "total limit published state")
    except BaseException as exc:
        return _fail(
            gate_id,
            name,
            "OpLog boundary probe failed: %s:%s"
            % (getattr(exc, "code", type(exc).__name__), str(exc)),
        )
    finally:
        operation_module._MAX_OPLOG_RECORD_BYTES = original_record_limit
        operation_module._MAX_OPLOG_BYTES = original_total_limit
    return _ok(gate_id, name, "path+json+limits fail closed; permissions/hash stay stable")


