def check_cmd_01_unique_id() -> GateResult:
    """register 同 id 抛 validation_failed."""
    from command import CommandRegistry, CommandSpec
    from entity import ZeError
    from operation import new_operation
    reg = CommandRegistry()
    spec_a = CommandSpec(id="x", label="a",
                         execute=lambda **kw: new_operation(
                             command_id="x", source=kw["source"],
                             actor=kw["actor"].to_dict(),
                             patches=[], reverse_patches=[]))
    reg.register(spec_a)
    try:
        reg.register(CommandSpec(id="x", label="b", execute=spec_a.execute))
        return _fail("GATE-CMD-01", "command_unique_id", "duplicate id was accepted")
    except ZeError as e:
        if e.code != "validation_failed":
            return _fail("GATE-CMD-01", "command_unique_id", f"wrong code: {e.code}")
