def check_cmd_04_execute_returns_operation() -> GateResult:
    """execute 接受 Operation/CommandMutation；其他结果抛 validation_failed。"""
    from command import CommandMutation, CommandRegistry, CommandSpec
    from document import Document
    from entity import Actor, ZeError
    from operation import new_operation
    reg = CommandRegistry()
    reg.register(CommandSpec(
        id="bad", label="bad",
        execute=lambda **kw: "not an Operation",
    ))
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    try:
        reg.dispatch("bad", {}, actor=Actor(user_id="u1"), source="user", doc=doc)
        return _fail("GATE-CMD-04", "command_execute_returns_operation",
                     "non-Operation return was accepted")
    except ZeError as e:
        if e.code != "validation_failed":
            return _fail("GATE-CMD-04", "command_execute_returns_operation",
                         f"wrong code: {e.code}")
    op = new_operation(
        command_id="good.batch", source="user", actor={"user_id": "u1"},
        patches=[], reverse_patches=[],
    )
    good = CommandRegistry()
    good.register(CommandSpec(
        id="good", label="good", execute=lambda **kw: CommandMutation((op,)),
    ))
    result = good.dispatch("good", {}, actor=Actor(user_id="u1"), source="user", doc=doc)
    if not isinstance(result, CommandMutation):
        return _fail("GATE-CMD-04", "command_execute_returns_operation",
                     "CommandMutation return was rejected")
    return _ok("GATE-CMD-04", "command_execute_returns_operation")


