def check_ft_07_sanitize_strips_control() -> GateResult:
    """sanitize 剔除控制字符、保留 \\t\\n\\r、按 maxLength 截断、对象递归且不改原值。"""
    from field_types import sanitize
    if sanitize("a\x00b\x07c\td\ne") != "abc\td\ne":
        return _fail("GATE-FT-07", "sanitize_strips_control", "control chars not stripped or \\t\\n removed")
    if sanitize("hello", {"type": "string", "maxLength": 3}) != "hel":
        return _fail("GATE-FT-07", "sanitize_strips_control", "maxLength not enforced")
    src = {"x": "p\x00q"}
    out = sanitize(src, {"type": "object", "properties": {"x": {"type": "string"}}})
    if out != {"x": "pq"} or src != {"x": "p\x00q"}:
        return _fail("GATE-FT-07", "sanitize_strips_control", "object recursion or immutability broken")
    return _ok("GATE-FT-07", "sanitize_strips_control")


# ---- AI (05-ai-coworker; AiGovernor 组合既有原语) ----

def _ai_reg(governor):
    """建一个挂了 governor、允许 user/ai 的最小命令注册表 + 注册空操作命令的 helper。"""
    from command import CommandRegistry, CommandSpec
    from operation import new_operation
    reg = CommandRegistry(ai_governor=governor)

    def _mk(cid, **extra):
        reg.register(CommandSpec(
            id=cid, label="x", sources_allowed=("user", "ai"),
            execute=lambda **kw: new_operation(
                command_id=cid, source=kw["source"], actor=kw["actor"].to_dict(),
                patches=[], reverse_patches=[]),
            **extra))
    return reg, _mk


def check_ai_01_provenance_required() -> GateResult:
    """source='ai' 缺 provenance → ai_provenance_required;带 provenance 放行。"""
    from ai_governor import AiGovernor
    from document import Document
    from entity import Actor, ZeError
    reg, mk = _ai_reg(AiGovernor(require_provenance=True))
    mk("c")
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    try:
        reg.dispatch("c", {}, actor=Actor(user_id="u"), source="ai", doc=doc)
        return _fail("GATE-AI-01", "provenance_required_when_source_ai", "missing provenance not rejected")
    except ZeError as e:
        if e.code != "ai_provenance_required":
            return _fail("GATE-AI-01", "provenance_required_when_source_ai", f"wrong code: {e.code}")
    op = reg.dispatch("c", {"provenance": {"actor": "u", "model": "m"}},
                      actor=Actor(user_id="u"), source="ai", doc=doc)
    if op is None:
        return _fail("GATE-AI-01", "provenance_required_when_source_ai", "valid provenance rejected")
    return _ok("GATE-AI-01", "provenance_required_when_source_ai")


def check_ai_04_safety_filter_applied() -> GateResult:
    """挂 deny-moderator → 不安全 ai 输入 raise ai_safety_blocked;安全输入放行。"""
    from ai_governor import AiGovernor
    from document import Document
    from entity import Actor, ZeError
    reg, mk = _ai_reg(AiGovernor(moderator=lambda t: "bad" not in t, require_provenance=False))
    mk("c")
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    try:
        reg.dispatch("c", {"prompt": "this is bad"}, actor=Actor(user_id="u"), source="ai", doc=doc)
        return _fail("GATE-AI-04", "ai_io_safety_filter_applied", "unsafe input not blocked")
    except ZeError as e:
        if e.code != "ai_safety_blocked":
            return _fail("GATE-AI-04", "ai_io_safety_filter_applied", f"wrong code: {e.code}")
    op = reg.dispatch("c", {"prompt": "all good"}, actor=Actor(user_id="u"), source="ai", doc=doc)
    if op is None:
        return _fail("GATE-AI-04", "ai_io_safety_filter_applied", "safe input rejected")
    return _ok("GATE-AI-04", "ai_io_safety_filter_applied")


def check_ai_05_high_risk_needs_approval() -> GateResult:
    """ai_high_risk 命令 source='ai' → 返回 PendingConfirmation(人审),不直接执行。"""
    from ai_governor import AiGovernor
    from document import Document
    from entity import Actor
    from operation import PendingConfirmation
    reg, mk = _ai_reg(AiGovernor(require_provenance=False))
    mk("risky", ai_high_risk=True)
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    r = reg.dispatch("risky", {}, actor=Actor(user_id="u"), source="ai", doc=doc)
    if not isinstance(r, PendingConfirmation):
        return _fail("GATE-AI-05", "high_risk_needs_approval", "high-risk ai cmd executed without approval")
    return _ok("GATE-AI-05", "high_risk_needs_approval")


def check_ai_06_cost_cap_enforced() -> GateResult:
    """单次估算 cost 超 per-call cap → ai_cost_exceeded;低成本放行。"""
    from ai_governor import AiGovernor
    from document import Document
    from entity import Actor, ZeError
    reg, mk = _ai_reg(AiGovernor(per_call_cap_usd=0.10, require_provenance=False))
    mk("pricey", ai_cost_usd=0.5)
    mk("cheap", ai_cost_usd=0.01)
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    try:
        reg.dispatch("pricey", {}, actor=Actor(user_id="u"), source="ai", doc=doc)
        return _fail("GATE-AI-06", "cost_cap_enforced", "over-cap cost not rejected")
    except ZeError as e:
        if e.code != "ai_cost_exceeded":
            return _fail("GATE-AI-06", "cost_cap_enforced", f"wrong code: {e.code}")
    op = reg.dispatch("cheap", {}, actor=Actor(user_id="u"), source="ai", doc=doc)
    if op is None:
        return _fail("GATE-AI-06", "cost_cap_enforced", "under-cap cost rejected")
    return _ok("GATE-AI-06", "cost_cap_enforced")


# ---- PROTO ----

def check_proto_01_change_kind_valid() -> GateResult:
    """EntityChange.change_kind ∈ CHANGE_KINDS."""
    from change_set import affected_entities, CHANGE_KINDS
    from document import Document
    from entity import Entity, Actor
    from operation import Patch, new_operation, ENTITY_META_FIELD
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    e = Entity(type="t", data={"x": 1}, id="e1")
    doc.add(e)
    # 各种 op 类型 → 各种 change_kind
    test_cases = [
        # (patch op, expected change_kind)
        ("create", "created"),
        ("set", "updated"),
        ("soft_delete", "soft_deleted"),
        ("restore", "restored"),
        ("delete", "hard_removed"),
    ]
    for patch_op, expected_kind in test_cases:
        if patch_op in ("create",):
            patch = Patch("t", "tmp", ENTITY_META_FIELD, patch_op, None, e.to_dict())
        elif patch_op in ("soft_delete", "restore", "delete"):
            patch = Patch("t", "e1", ENTITY_META_FIELD, patch_op, e.to_dict(), None)
        else:
            patch = Patch("t", "e1", "x", patch_op, 1, 2)
        op = new_operation(
            command_id="x", source="user", actor={"user_id": "u1"},
            patches=[patch], reverse_patches=[],
        )
        changes = affected_entities(op, doc)
        if not changes:
            return _fail("GATE-PROTO-01", "change_kind_valid",
                         f"no changes for op={patch_op}")
        ck = changes[0].change_kind
        if ck not in CHANGE_KINDS:
            return _fail("GATE-PROTO-01", "change_kind_valid",
                         f"change_kind {ck!r} not in CHANGE_KINDS")
        if ck != expected_kind:
            return _fail("GATE-PROTO-01", "change_kind_valid",
                         f"op={patch_op}: expected {expected_kind}, got {ck}")
    return _ok("GATE-PROTO-01", "change_kind_valid")


def check_proto_02_broadcast_payload_format() -> GateResult:
    """to_broadcast_payload 输出含 type='entity_change' + 必需字段."""
    from change_set import to_broadcast_payload, affected_entities
    from document import Document
    from entity import Entity
    from operation import Patch, new_operation, ENTITY_META_FIELD
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={}, id="e1"))
    op = new_operation(
        command_id="x", source="user", actor={"user_id": "u1"},
        patches=[Patch("t", "e1", "k", "set", None, 1)],
        reverse_patches=[Patch("t", "e1", "k", "set", 1, None)],
    )
    changes = affected_entities(op, doc)
    payload = to_broadcast_payload(op, changes, doc_id="my-doc")
    required = {"type", "doc_id", "op_id", "trace_id", "source", "actor", "ts",
                "command_id", "changes"}
    missing = required - payload.keys()
    if missing:
        return _fail("GATE-PROTO-02", "broadcast_payload_format",
                     f"missing keys: {missing}")
    if payload["type"] != "entity_change":
        return _fail("GATE-PROTO-02", "broadcast_payload_format",
                     f"wrong type: {payload['type']!r}")
    return _ok("GATE-PROTO-02", "broadcast_payload_format")


def check_proto_03_snapshot_unless_hard_removed() -> GateResult:
    """EntityChange.snapshot 必有 (除非 hard_removed)."""
    from change_set import affected_entities
    from document import Document
    from entity import Entity
    from operation import Patch, new_operation, ENTITY_META_FIELD
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    e = Entity(type="t", data={"x": 1}, id="e1")
    doc.add(e)

    # updated → snapshot 必有
    op_up = new_operation(
        command_id="x", source="user", actor={"user_id": "u1"},
        patches=[Patch("t", "e1", "x", "set", 1, 2)],
        reverse_patches=[Patch("t", "e1", "x", "set", 2, 1)],
    )
    changes = affected_entities(op_up, doc)
    if not changes or changes[0].snapshot is None:
        return _fail("GATE-PROTO-03", "snapshot_unless_hard_removed",
                     "updated change has no snapshot")

    # hard_removed → snapshot=None 允许
    snap = e.to_dict()
    doc.hard_remove("t", "e1")
    op_hr = new_operation(
        command_id="x", source="user", actor={"user_id": "u1"},
        patches=[Patch("t", "e1", ENTITY_META_FIELD, "delete", snap, None)],
        reverse_patches=[Patch("t", "e1", ENTITY_META_FIELD, "create", None, snap)],
    )
    changes = affected_entities(op_hr, doc)
    if not changes:
        return _fail("GATE-PROTO-03", "snapshot_unless_hard_removed",
                     "no changes for hard_removed")
    if changes[0].snapshot is not None:
        return _fail("GATE-PROTO-03", "snapshot_unless_hard_removed",
                     "hard_removed should have snapshot=None")
    return _ok("GATE-PROTO-03", "snapshot_unless_hard_removed")


def check_proto_04_entity_change_ordering() -> GateResult:
    """affected_entities 返回按 (entity_type, entity_id) sorted."""
    from change_set import affected_entities
    from document import Document
    from entity import Entity
    from operation import Patch, new_operation
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    for et, eid in [("zebra", "a"), ("alpha", "b"), ("mid", "c")]:
        doc.add(Entity(type=et, data={}, id=eid))
    # patches 故意乱序
    op = new_operation(
        command_id="x", source="user", actor={"user_id": "u1"},
        patches=[
            Patch("zebra", "a", "k", "set", 0, 1),
            Patch("alpha", "b", "k", "set", 0, 1),
            Patch("mid", "c", "k", "set", 0, 1),
        ],
        reverse_patches=[],
    )
    changes = affected_entities(op, doc)
    types = [c.entity_type for c in changes]
    if types != sorted(types):
        return _fail("GATE-PROTO-04", "entity_change_ordering",
                     f"not sorted: {types}")
    return _ok("GATE-PROTO-04", "entity_change_ordering")


# ---- CAP (05-capacity-limit) ----

def check_cap_01_limits_from_env() -> GateResult:
    """CapacityLimits.from_env 正常读取 + 非法值抛 capacity_config_invalid."""
    from capacity import CapacityLimits, DEFAULT_LIMITS
    from entity import ZeError
    # happy: 空 env → default
    lim = CapacityLimits.from_env(env={})
    if lim != CapacityLimits():
        return _fail("GATE-CAP-01", "capacity_limits_from_env",
                     "empty env did not return default")
    # happy: 部分注入
    lim2 = CapacityLimits.from_env(env={
        "ZE_CAPACITY_ENTITY_COUNT_MAX": "42",
        "ZE_CAPACITY_DOC_TOTAL_ASSETS_SIZE_MAX": "2048",
    })
    if lim2.entity_count_max != 42:
        return _fail("GATE-CAP-01", "capacity_limits_from_env",
                     f"env override failed: {lim2.entity_count_max}")
    if lim2.entity_data_size_max != DEFAULT_LIMITS.entity_data_size_max:
        return _fail("GATE-CAP-01", "capacity_limits_from_env",
                     "non-overridden fields should fallback to default")
    if lim2.doc_total_assets_size_max != 2048:
        return _fail(
            "GATE-CAP-01", "capacity_limits_from_env",
            "project asset total env override failed",
        )
    # sad: 非法整数
    try:
        CapacityLimits.from_env(env={"ZE_CAPACITY_ENTITY_COUNT_MAX": "abc"})
        return _fail("GATE-CAP-01", "capacity_limits_from_env",
                     "invalid int did not raise")
    except ZeError as e:
        if e.code != "capacity_config_invalid":
            return _fail("GATE-CAP-01", "capacity_limits_from_env",
                         f"wrong error code: {e.code}")
    # sad: 非正数
    try:
        CapacityLimits.from_env(env={"ZE_CAPACITY_ENTITY_COUNT_MAX": "0"})
        return _fail("GATE-CAP-01", "capacity_limits_from_env",
                     "zero did not raise")
    except ZeError as e:
        if e.code != "capacity_config_invalid":
            return _fail("GATE-CAP-01", "capacity_limits_from_env",
                         f"wrong error code on zero: {e.code}")
    return _ok("GATE-CAP-01", "capacity_limits_from_env")


def check_cap_02_exceeded_throws() -> GateResult:
    """Every functional capacity check rejects overflow with exact evidence."""
    from types import SimpleNamespace
    from capacity import CapacityChecker, CapacityLimits
    from document import Document
    from entity import Entity, ZeError

    c = CapacityChecker(CapacityLimits(
        entity_count_max=1,
        entity_data_size_max=10,
        entity_field_count_max=2,
        asset_blob_size_max=100,
        doc_total_assets_size_max=100,
    ))
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={}, id="e1"))

    def _verify(check_call, expected_limit_name):
        try:
            check_call()
            return f"{expected_limit_name}: did not raise"
        except ZeError as e:
            if e.code != "capacity_exceeded":
                return f"{expected_limit_name}: wrong code {e.code}"
            ctx = e.context or {}
            for key in ("limit_name", "limit", "actual"):
                if key not in ctx:
                    return f"{expected_limit_name}: missing {key}"
            if ctx["limit_name"] != expected_limit_name:
                return (f"{expected_limit_name}: limit_name was "
                        f"{ctx['limit_name']}")
        return None

    # 1) entity_count_max
    err = _verify(lambda: c.check_add_entity(doc), "entity_count_max")
    if err:
        return _fail("GATE-CAP-02", "capacity_exceeded_throws", err)

    # 2) entity_data_size_max
    big = Entity(type="t", data={"x": "y" * 100})
    err = _verify(lambda: c.check_entity_data(big), "entity_data_size_max")
    if err:
        return _fail("GATE-CAP-02", "capacity_exceeded_throws", err)

    # 3) entity_field_count_max  (要独立 checker; 上面 data_size_max=10 会先触发)
    c_field = CapacityChecker(CapacityLimits(
        entity_count_max=10_000,
        entity_data_size_max=1_000_000,
        entity_field_count_max=2,
        asset_blob_size_max=100,
    ))
    many = Entity(type="t", data={"a": 1, "b": 2, "c": 3})
    err = _verify(lambda: c_field.check_entity_data(many), "entity_field_count_max")
    if err:
        return _fail("GATE-CAP-02", "capacity_exceeded_throws", err)

    # 4) asset_blob_size_max
    err = _verify(lambda: c.check_asset_blob(101), "asset_blob_size_max")
    if err:
        return _fail("GATE-CAP-02", "capacity_exceeded_throws", err)

    # 5) doc_total_assets_size_max includes the proposed unique blob.
    err = _verify(
        lambda: c.check_doc_total_assets(
            SimpleNamespace(total_size=lambda: 90), additional_size=11,
        ),
        "doc_total_assets_size_max",
    )
    if err:
        return _fail("GATE-CAP-02", "capacity_exceeded_throws", err)

    return _ok("GATE-CAP-02", "capacity_exceeded_throws")


def check_cap_03_measure_entity() -> GateResult:
    """measure_entity 返回 data_size + field_count, 跟实际 JSON 字节数 / 递归字段数一致."""
    import json
    from capacity import CapacityChecker
    from entity import Entity

    c = CapacityChecker()

    # 平 dict
    e1 = Entity(type="t", data={"name": "你好", "n": 42})
    m1 = c.measure_entity(e1)
    expected_size = len(
        json.dumps({"name": "你好", "n": 42}, ensure_ascii=False).encode("utf-8")
    )
    if m1.get("data_size") != expected_size:
        return _fail("GATE-CAP-03", "capacity_measure_entity",
                     f"data_size mismatch: {m1.get('data_size')} != {expected_size}")
    if m1.get("field_count") != 2:
        return _fail("GATE-CAP-03", "capacity_measure_entity",
                     f"flat field_count expected 2, got {m1.get('field_count')}")

    # 嵌套 dict: {"a": {"b": 1, "c": 2}, "d": 3} → 4 fields
    e2 = Entity(type="t", data={"a": {"b": 1, "c": 2}, "d": 3})
    m2 = c.measure_entity(e2)
    if m2.get("field_count") != 4:
        return _fail("GATE-CAP-03", "capacity_measure_entity",
                     f"nested field_count expected 4, got {m2.get('field_count')}")

    # list of dict: {"xs": [{"a": 1}, {"b": 2}]} → 3 fields
    e3 = Entity(type="t", data={"xs": [{"a": 1}, {"b": 2}]})
    m3 = c.measure_entity(e3)
    if m3.get("field_count") != 3:
        return _fail("GATE-CAP-03", "capacity_measure_entity",
                     f"list-of-dict field_count expected 3, got {m3.get('field_count')}")

    return _ok("GATE-CAP-03", "capacity_measure_entity")


# ---- UNDO (04-history-rollback) ----

def _undo_setup():
    """构造一个含 user op 的环境: doc + op_log + UndoController."""
    from document import Document
    from entity import Actor, Entity
    from operation import OpLog, Patch, new_operation
    from undo import UndoController
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={"x": 0}, id="e1"))
    log = OpLog()
    actor = Actor(user_id="u1")
    # 模拟一次用户操作 x: 0 → 42
    _apply_history_patch(doc,
        Patch("t", "e1", "x", "set", 0, 42), actor=actor,
    )
    log.append(new_operation(
        command_id="set_x", source="user", actor=actor.to_dict(),
        patches=[Patch("t", "e1", "x", "set", 0, 42)],
        reverse_patches=[Patch("t", "e1", "x", "set", 42, 0)],
    ))
    return doc, log, actor, UndoController(log, doc)


def check_undo_01_produces_rollback_op() -> GateResult:
    """undo 后 OpLog 末尾应是 kind=rollback 的 op."""
    doc, log, actor, ctl = _undo_setup()
    result = ctl.undo(actor=actor)
    if result is None or not result:
        return _fail("GATE-UNDO-01", "undo_produces_rollback_op",
                     "undo returned None / empty")
    last_entry = log.entries()[-1]
    if last_entry["op"].get("kind") != "rollback":
        return _fail("GATE-UNDO-01", "undo_produces_rollback_op",
                     f"last op kind={last_entry['op'].get('kind')!r}, expected 'rollback'")
    return _ok("GATE-UNDO-01", "undo_produces_rollback_op")


def check_undo_02_redo_inverts_undo() -> GateResult:
    """undo 后 redo 应恢复原数据."""
    doc, log, actor, ctl = _undo_setup()
    if doc.get("t", "e1").data["x"] != 42:
        return _fail("GATE-UNDO-02", "redo_inverts_undo",
                     "pre-condition: x should be 42")
    ctl.undo(actor=actor)
    if doc.get("t", "e1").data["x"] != 0:
        return _fail("GATE-UNDO-02", "redo_inverts_undo",
                     f"after undo x={doc.get('t', 'e1').data['x']}, expected 0")
    ctl.redo(actor=actor)
    if doc.get("t", "e1").data["x"] != 42:
        return _fail("GATE-UNDO-02", "redo_inverts_undo",
                     f"after redo x={doc.get('t', 'e1').data['x']}, expected 42")
    return _ok("GATE-UNDO-02", "redo_inverts_undo")


def check_undo_03_apply_patch_set() -> GateResult:
    """apply_patch_directly 处理 set patch 正确 (走 CAS + bump version)."""
    from document import Document
    from entity import Actor, Entity
    from operation import Patch
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={"x": 1}, id="e1"))
    actor = Actor(user_id="u1")
    v_before = doc.get("t", "e1").version
    _apply_history_patch(doc, Patch("t", "e1", "x", "set", 1, 99), actor=actor)
    if doc.get("t", "e1").data["x"] != 99:
        return _fail("GATE-UNDO-03", "apply_patch_set",
                     f"x={doc.get('t', 'e1').data['x']}, expected 99")
    if doc.get("t", "e1").version != v_before + 1:
        return _fail("GATE-UNDO-03", "apply_patch_set",
                     f"version not bumped: {doc.get('t', 'e1').version} vs {v_before}")
    return _ok("GATE-UNDO-03", "apply_patch_set")


def check_undo_04_apply_patch_meta_ops() -> GateResult:
    """apply_patch_directly 处理 create / soft_delete / restore / hard_remove."""
    from document import Document
    from entity import Actor, Entity
    from operation import ENTITY_META_FIELD, Patch
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    actor = Actor(user_id="u1")
    # create
    e_dict = Entity(type="t", data={"x": 1}, id="new1").to_dict()
    _apply_history_patch(doc,
        Patch("t", "new1", ENTITY_META_FIELD, "create", None, e_dict),
        actor=actor,
    )
    if doc.find("t", "new1") is None:
        return _fail("GATE-UNDO-04", "apply_patch_meta_ops",
                     "create did not add entity")
    # soft_delete
    _apply_history_patch(doc,
        Patch("t", "new1", ENTITY_META_FIELD, "soft_delete", e_dict, None),
        actor=actor,
    )
    if not doc.get("t", "new1").deleted:
        return _fail("GATE-UNDO-04", "apply_patch_meta_ops",
                     "soft_delete did not flip deleted=True")
    # restore
    _apply_history_patch(doc,
        Patch("t", "new1", ENTITY_META_FIELD, "restore", None, None),
        actor=actor,
    )
    if doc.get("t", "new1").deleted:
        return _fail("GATE-UNDO-04", "apply_patch_meta_ops",
                     "restore did not flip deleted=False")
    # hard_remove (op=delete with __entity__)
    _apply_history_patch(doc,
        Patch("t", "new1", ENTITY_META_FIELD, "delete", e_dict, None),
        actor=actor,
    )
    if doc.find("t", "new1") is not None:
        return _fail("GATE-UNDO-04", "apply_patch_meta_ops",
                     "hard_remove did not remove entity")
    return _ok("GATE-UNDO-04", "apply_patch_meta_ops")


def check_undo_05_group_id_aggregation() -> GateResult:
    """同 group_id 多 op 一次 undo 应反所有."""
    from document import Document
    from entity import Actor, Entity
    from operation import OpLog, Patch, new_operation
    from undo import UndoController
    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={"x": 0}, id="e1"))
    log = OpLog()
    actor = Actor(user_id="u1")
    g = "drag-1"
    for v_from, v_to in [(0, 1), (1, 2), (2, 3)]:
        _apply_history_patch(doc,
            Patch("t", "e1", "x", "set", v_from, v_to), actor=actor,
        )
        log.append(new_operation(
            command_id="drag", source="user", actor=actor.to_dict(),
            patches=[Patch("t", "e1", "x", "set", v_from, v_to)],
            reverse_patches=[Patch("t", "e1", "x", "set", v_to, v_from)],
            group_id=g,
        ))
    if doc.get("t", "e1").data["x"] != 3:
        return _fail("GATE-UNDO-05", "group_id_aggregation",
                     "pre-condition: x should be 3")
    ctl = UndoController(log, doc)
    ctl.undo(actor=actor)
    if doc.get("t", "e1").data["x"] != 0:
        return _fail("GATE-UNDO-05", "group_id_aggregation",
                     f"x={doc.get('t', 'e1').data['x']}, expected 0 (full group rolled back)")
    return _ok("GATE-UNDO-05", "group_id_aggregation")


# ---- RT (01-realtime-sync) ----

def _rt_make_payload(entity_type="t", entity_id="e1", doc_id=None,
                     change_kind="updated"):
    return {
        "type": "entity_change",
        "doc_id": doc_id,
        "op_id": "op-1",
        "trace_id": "trace-1",
        "source": "user",
        "command_id": "test",
        "actor": {"user_id": "u1"},
        "ts": 1.0,
        "changes": [{
            "entity_type": entity_type,
            "entity_id": entity_id,
            "change_kind": change_kind,
            "changed_fields": ["x"],
            "patches": [],
            "snapshot": {} if change_kind != "hard_removed" else None,
        }],
    }


def check_rt_01_publish_routes_to_subscribers() -> GateResult:
    """publish_change → 订阅者 callback 收到 payload."""
    from broker import RealtimeBroker
    broker = RealtimeBroker()
    received = []
    broker.subscribe(callback=lambda p: received.append(p))
    broker.publish_change(_rt_make_payload())
    if len(received) != 1:
        return _fail("GATE-RT-01", "broker_publish_routes_to_subscribers",
                     f"subscriber received {len(received)} messages, expected 1")
    return _ok("GATE-RT-01", "broker_publish_routes_to_subscribers")


def check_rt_02_subscribe_entity_type_filter() -> GateResult:
    """entity_type 过滤生效."""
    from broker import RealtimeBroker
    broker = RealtimeBroker()
    received = []
    broker.subscribe(entity_type="entry", callback=lambda p: received.append(p))
    broker.publish_change(_rt_make_payload(entity_type="entry"))
    broker.publish_change(_rt_make_payload(entity_type="other"))
    if len(received) != 1:
        return _fail("GATE-RT-02", "subscribe_entity_type_filter",
                     f"filter failed: {len(received)} received, expected 1")
    if received[0]["changes"][0]["entity_type"] != "entry":
        return _fail("GATE-RT-02", "subscribe_entity_type_filter",
                     "wrong entity_type received")
    return _ok("GATE-RT-02", "subscribe_entity_type_filter")


def check_rt_03_subscribe_since_seq_replay() -> GateResult:
    """since_seq 触发 replay buffer 中 seq >= since_seq 的消息."""
    from broker import RealtimeBroker
    broker = RealtimeBroker()
    for i in range(3):
        broker.publish_change(_rt_make_payload(entity_id=f"e{i}"))
    received = []
    broker.subscribe(
        callback=lambda p: received.append(p), since_seq=2,
    )
    if len(received) != 2:
        return _fail("GATE-RT-03", "subscribe_since_seq_replay",
                     f"since_seq=2 replayed {len(received)} messages, expected 2")
    expected_ids = ["e1", "e2"]
    actual_ids = [p["changes"][0]["entity_id"] for p in received]
    if actual_ids != expected_ids:
        return _fail("GATE-RT-03", "subscribe_since_seq_replay",
                     f"replay order: {actual_ids}, expected {expected_ids}")
    return _ok("GATE-RT-03", "subscribe_since_seq_replay")


def check_rt_04_unsubscribe_stops_delivery() -> GateResult:
    """unsubscribe 后 callback 不再被调."""
    from broker import RealtimeBroker
    broker = RealtimeBroker()
    received = []
    sub = broker.subscribe(callback=lambda p: received.append(p))
    broker.publish_change(_rt_make_payload())
    sub.unsubscribe()
    broker.publish_change(_rt_make_payload())
    if len(received) != 1:
        return _fail("GATE-RT-04", "unsubscribe_stops_delivery",
                     f"after unsubscribe received {len(received)}, expected 1")
    return _ok("GATE-RT-04", "unsubscribe_stops_delivery")


def check_rt_05_payload_format_entity_change() -> GateResult:
    """payload 含 type=entity_change + 必需字段 (_protocol §4.5)."""
    payload = _rt_make_payload()
    required = ["type", "doc_id", "op_id", "trace_id", "source",
                "command_id", "actor", "ts", "changes"]
    for key in required:
        if key not in payload:
            return _fail("GATE-RT-05", "payload_format_entity_change",
                         f"missing field {key!r}")
    if payload["type"] != "entity_change":
        return _fail("GATE-RT-05", "payload_format_entity_change",
                     f"type={payload['type']!r}, expected 'entity_change'")
    for change in payload["changes"]:
        for key in ["entity_type", "entity_id", "change_kind",
                    "changed_fields", "patches"]:
            if key not in change:
                return _fail("GATE-RT-05", "payload_format_entity_change",
                             f"change missing {key!r}")
    return _ok("GATE-RT-05", "payload_format_entity_change")


def check_rt_06_cmd_dispatch_has_no_commit_side_effects() -> GateResult:
    """CommandRegistry 即使收到旧 broker/op_log 参数也不提交.

    W03 起 canonical publish 与 OpLog append 都归 CommitCoordinator。本 gate
    防止旧的隐式副作用回流到 dispatch。
    """
    from broker import RealtimeBroker
    from command import CommandRegistry, CommandSpec
    from document import Document
    from entity import Actor, Entity
    from operation import OpLog, Patch, new_operation

    doc = Document(schema_version="1.0.0", collaboration_mode="with_save")
    doc.add(Entity(type="t", data={"x": 1}, id="e1"))
    broker = RealtimeBroker()
    received = []
    broker.subscribe(callback=lambda p: received.append(p))

    reg = CommandRegistry(broker=broker)

    def execute_fn(*, args, actor, source, doc):
        return new_operation(
            command_id="bump", source=source, actor=actor.to_dict(),
            patches=[Patch("t", "e1", "x", "set", 1, 2)],
            reverse_patches=[Patch("t", "e1", "x", "set", 2, 1)],
        )

    reg.register(CommandSpec(id="bump", label="Bump", execute=execute_fn))
    actor = Actor(user_id="u1")
    op_log = OpLog()
    op = reg.dispatch("bump", {}, actor=actor, source="user", doc=doc, op_log=op_log)

    gate_name = "cmd_dispatch_has_no_commit_side_effects"
    if getattr(op, "command_id", None) != "bump":
        return _fail("GATE-RT-06", gate_name,
                     "dispatch did not return the handler Operation")
    if received:
        return _fail("GATE-RT-06", gate_name,
                     f"dispatch published outside CommitCoordinator; received={len(received)}")
    if len(op_log) != 0:
        return _fail("GATE-RT-06", gate_name,
                     f"dispatch appended outside CommitCoordinator; entries={len(op_log)}")
    return _ok("GATE-RT-06", gate_name)


