def _history_authority_constant_text(node: Any) -> str | None:
    """Fold the small constant-string forms relevant to import bypasses."""
    import ast

    if isinstance(node, ast.Constant) and type(node.value) is str:
        return node.value
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        left = _history_authority_constant_text(node.left)
        right = _history_authority_constant_text(node.right)
        if left is not None and right is not None:
            return left + right
    if isinstance(node, ast.JoinedStr):
        parts = [_history_authority_constant_text(value) for value in node.values]
        if all(part is not None for part in parts):
            return "".join(part for part in parts if part is not None)
    return None


def _history_authority_import_records(
    source: str,
    *,
    filename: str = "<source>",
) -> tuple[list[tuple[str, str, int]], list[str]]:
    """Return exact named imports and broad/dynamic registry escapes.

    A named import remains reviewable as one member owned by one file.  A
    module import, star import, dynamic import, or ``sys.modules`` lookup hands
    the caller the entire module and therefore every private capability.
    """
    import ast

    tree = ast.parse(source, filename=filename)
    dynamic_import_names = {"__import__", "import_module"}
    sys_names = {"sys"}
    modules_names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == "sys":
                    sys_names.add(alias.asname or alias.name)
        elif isinstance(node, ast.ImportFrom) and node.module:
            if node.module == "importlib":
                dynamic_import_names.update(
                    alias.asname or alias.name
                    for alias in node.names
                    if alias.name == "import_module"
                )
            elif node.module == "builtins":
                dynamic_import_names.update(
                    alias.asname or alias.name
                    for alias in node.names
                    if alias.name == "__import__"
                )
            elif node.module == "sys":
                modules_names.update(
                    alias.asname or alias.name
                    for alias in node.names
                    if alias.name == "modules"
                )

    def is_sys_modules(value: ast.AST) -> bool:
        return (
            isinstance(value, ast.Attribute)
            and value.attr == "modules"
            and isinstance(value.value, ast.Name)
            and value.value.id in sys_names
        ) or (
            isinstance(value, ast.Name) and value.id in modules_names
        )

    # Preserve the common ``loaded = sys.modules`` alias so the obvious
    # registry bypass does not evade the direct syntax check.
    changed = True
    while changed:
        changed = False
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            value = node.value
            if value is None or not is_sys_modules(value):
                continue
            for target in targets:
                if isinstance(target, ast.Name) and target.id not in modules_names:
                    modules_names.add(target.id)
                    changed = True

    imports: list[tuple[str, str, int]] = []
    escapes: list[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.rsplit(".", 1)[-1] == "history_authority":
                    escapes.append(
                        f"{filename}:{node.lineno}:broad-import:{alias.name}"
                    )
        elif isinstance(node, ast.ImportFrom) and node.module:
            if node.module.rsplit(".", 1)[-1] == "history_authority":
                for alias in node.names:
                    imports.append((alias.name, alias.asname or "", node.lineno))
                    if alias.name == "*":
                        escapes.append(
                            f"{filename}:{node.lineno}:star-import:history_authority"
                        )
            elif any(alias.name == "history_authority" for alias in node.names):
                escapes.append(
                    f"{filename}:{node.lineno}:broad-from-import:{node.module}"
                )
        elif isinstance(node, ast.Call):
            call_name = _gate_ast_call_name(node)
            if call_name in dynamic_import_names and node.args:
                module = _history_authority_constant_text(node.args[0])
                if (
                    module is not None
                    and module.rsplit(".", 1)[-1] == "history_authority"
                ):
                    escapes.append(
                        f"{filename}:{node.lineno}:dynamic-import:{module}"
                    )
            if (
                isinstance(node.func, ast.Attribute)
                and is_sys_modules(node.func.value)
                and node.args
            ):
                module = _history_authority_constant_text(node.args[0])
                if (
                    module is not None
                    and module.rsplit(".", 1)[-1] == "history_authority"
                ):
                    escapes.append(
                        f"{filename}:{node.lineno}:sys-modules:{module}"
                    )
        elif isinstance(node, ast.Subscript) and is_sys_modules(node.value):
            module = _history_authority_constant_text(node.slice)
            if (
                module is not None
                and module.rsplit(".", 1)[-1] == "history_authority"
            ):
                escapes.append(
                    f"{filename}:{node.lineno}:sys-modules:{module}"
                )
    return sorted(imports), sorted(set(escapes))


def _history_authority_is_test_source(relative: Path) -> bool:
    return bool(
        relative.name == "conftest.py"
        or relative.name.startswith("test_")
        or relative.name.endswith("_test.py")
        or "tests" in relative.parts
    )


def _history_authority_production_inventory(
    skill_root: Path,
) -> tuple[dict[str, tuple[tuple[str, str], ...]], list[str]]:
    """Census every production import of the process-local history authority."""
    imports: dict[str, list[tuple[str, str]]] = {}
    escapes: list[str] = []
    root = Path(skill_root).resolve()
    for path in _iter_auditable_python_sources(root):
        relative = path.resolve().relative_to(root)
        if _history_authority_is_test_source(relative):
            continue
        try:
            source = path.read_text(encoding="utf-8")
            records, found_escapes = _history_authority_import_records(
                source,
                filename=relative.as_posix(),
            )
        except (OSError, SyntaxError, UnicodeError) as exc:
            escapes.append(
                f"{relative.as_posix()}:0:source-unreadable:{type(exc).__name__}"
            )
            continue
        if records:
            imports[relative.as_posix()] = [
                (member, alias) for member, alias, _line in records
            ]
        escapes.extend(found_escapes)
    return (
        {
            path: tuple(sorted(records))
            for path, records in sorted(imports.items())
        },
        sorted(set(escapes)),
    )


def _history_authority_literal_all(
    source: str,
    *,
    filename: str,
) -> tuple[set[str], set[str]]:
    """Return one literal ``__all__`` and the module's top-level names."""
    import ast

    tree = ast.parse(source, filename=filename)
    all_nodes: list[ast.AST] = []
    top_names: set[str] = set()
    for node in tree.body:
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            top_names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    top_names.add(target.id)
                    if target.id == "__all__":
                        all_nodes.append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            top_names.add(node.target.id)
            if node.target.id == "__all__" and node.value is not None:
                all_nodes.append(node.value)
    if len(all_nodes) != 1:
        raise ValueError(f"{filename} must define one literal __all__")
    value = ast.literal_eval(all_nodes[0])
    if (
        not isinstance(value, (list, tuple))
        or any(type(item) is not str for item in value)
    ):
        raise ValueError(f"{filename} __all__ must be a string list/tuple")
    return set(value), top_names


def _history_authority_public_surface_violations(
    history_source: str,
    sdk_source: str,
    public_lock_source: str,
) -> list[str]:
    """Keep raw transactions and private authority ports off public surfaces."""
    import json

    try:
        history_all, history_names = _history_authority_literal_all(
            history_source,
            filename="history_authority.py",
        )
        sdk_all, _sdk_names = _history_authority_literal_all(
            sdk_source,
            filename="sdk/__init__.py",
        )
        public_lock = json.loads(public_lock_source)
        locked_names = set(public_lock.get("py", {}))
    except (SyntaxError, ValueError, TypeError, json.JSONDecodeError) as exc:
        return [f"public-surface-unreadable:{type(exc).__name__}:{exc}"]

    private_names = {
        name
        for name in history_names
        if (
            (name.startswith("_HISTORY_") and name.endswith("_CAPABILITY"))
            or (name.startswith("_history_") and name.endswith("_port"))
            or name.startswith("_History")
            or name in {
                "_CoordinatorHistoryPort",
                "_history_oplog_is_bound",
                "_issue_history_bind_capability",
            }
        )
    }
    raw_transaction_names = {"HistoryTransaction", "current_history_transaction"}
    forbidden = private_names.union(raw_transaction_names)
    violations: list[str] = []
    if "current_history_transaction" in history_names:
        violations.append("raw-transaction-lookup-defined:current_history_transaction")
    history_leaks = sorted(history_all.intersection(forbidden))
    if history_leaks:
        violations.append(f"history-__all__:{history_leaks!r}")
    underscore_exports = sorted(name for name in history_all if name.startswith("_"))
    if underscore_exports:
        violations.append(f"history-private-exports:{underscore_exports!r}")
    sdk_leaks = sorted(sdk_all.intersection(forbidden))
    if sdk_leaks:
        violations.append(f"sdk-__all__:{sdk_leaks!r}")
    lock_leaks = sorted(locked_names.intersection(forbidden))
    if lock_leaks:
        violations.append(f"public-lock:{lock_leaks!r}")
    return violations


def check_commit_01_durable_before_visibility() -> GateResult:
    """真实 file adapter 必须 save→append→publish，事件带提交身份与耐久版本。"""
    import tempfile
    from types import SimpleNamespace
    from unittest.mock import patch
    from document import Document
    from operation import OpLog, new_operation
    from file_store import FileCommitStore
    from commit_coordinator import BrokerEventPublisher, CommitCoordinator

    name = "commit_durable_before_visibility"
    with tempfile.TemporaryDirectory() as td:
        order: list[str] = []
        doc = Document(
            schema_version="1.0.0", collaboration_mode="live_collab",
        )
        real_save = Document.save

        def observed_save(self, path, expected_version=None):
            if self is doc:
                order.append("save")
            return real_save(self, path, expected_version=expected_version)

        oplog = OpLog(Path(td) / "oplog.ndjson")
        real_append = oplog.append
        oplog.append = lambda op: order.append("append") or real_append(op)
        payloads: list[dict[str, Any]] = []
        broker = SimpleNamespace(
            publish_change=lambda payload: order.append("publish") or payloads.append(payload)
        )
        op = new_operation(
            command_id="gate.commit", source="system", actor={"user_id": "__gate__"},
            patches=[], reverse_patches=[], document_id=doc.id,
        )
        with patch.object(Document, "save", observed_save):
            execution = CommitCoordinator(
                doc,
                FileCommitStore(Path(td) / "document.json", oplog),
                publisher=BrokerEventPublisher(broker),
            ).execute(lambda: op)

    if order != ["save", "append", "publish"]:
        return _fail("GATE-COMMIT-01", name, f"wrong order: {order}")
    if not execution.is_committed or len(payloads) != 1:
        return _fail("GATE-COMMIT-01", name, "commit or publication missing")
    payload = payloads[0]
    if (not payload.get("commit_id")
            or payload.get("document_version") != execution.receipt.document_version):
        return _fail("GATE-COMMIT-01", name, "canonical event lacks commit identity/version")
    return _ok("GATE-COMMIT-01", name)


def check_commit_02_production_surfaces_use_coordinator() -> GateResult:
    """生产接线统一走 coordinator，history authority 私权只有精确 owner。"""
    import ast

    name = "production_surfaces_use_commit_coordinator"
    root = _CORE.parent
    surface_paths = {
        root / "server.py": "commit",
        root / "sdk" / "mcp_bridge.py": "commit",
        root / "scripts" / "ze_command.py": "commit",
        _CORE / "03-commands-operations" / "03-pipeline" / "supervisor.py": (
            "_commit_coordinator"
        ),
    }

    def _tree(path: Path):
        try:
            return ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        except (OSError, SyntaxError) as exc:
            raise RuntimeError(f"cannot parse {path.name}: {exc}") from exc

    try:
        trees = {path: _tree(path) for path in surface_paths}
        bootstrap_path = root / "sdk" / "bootstrap.py"
        bootstrap_tree = _tree(bootstrap_path)
    except RuntimeError as exc:
        return _fail("GATE-COMMIT-02", name, str(exc))

    for path, owner_attr in surface_paths.items():
        found = any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "execute"
            and isinstance(node.func.value, ast.Attribute)
            and node.func.value.attr == owner_attr
            for node in ast.walk(trees[path])
        )
        if not found:
            return _fail(
                "GATE-COMMIT-02", name,
                f"{path.name} has no AST call through {owner_attr}.execute",
            )

    wired = any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "PipelineSupervisor"
        and any(
            keyword.arg == "commit_coordinator"
            and isinstance(keyword.value, ast.Name)
            and keyword.value.id == "commit"
            for keyword in node.keywords
        )
        for node in ast.walk(bootstrap_tree)
    )
    if not wired:
        return _fail("GATE-COMMIT-02", name, "bootstrap does not inject project coordinator")

    forbidden = {
        root / "server.py": "_finalize_command_op",
        root / "sdk" / "mcp_bridge.py": "_finalize",
        root / "scripts" / "ze_command.py": "_finalize_cli_op",
    }
    for path, function_name in forbidden.items():
        tree = trees[path]
        if any(
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name == function_name
            for node in ast.walk(tree)
        ):
            return _fail("GATE-COMMIT-02", name, f"legacy finalizer returned in {path.name}")

    actual_imports, import_escapes = _history_authority_production_inventory(root)
    if import_escapes:
        return _fail(
            "GATE-COMMIT-02",
            name,
            "history authority gained a broad/dynamic/registry import",
            evidence={"escapes": import_escapes},
        )
    if actual_imports != _HISTORY_AUTHORITY_PRODUCTION_IMPORTS:
        return _fail(
            "GATE-COMMIT-02",
            name,
            "history authority import ownership changed",
            evidence={
                "expected": _HISTORY_AUTHORITY_PRODUCTION_IMPORTS,
                "actual": actual_imports,
            },
        )

    history_path = root / "01-core" / "_protocol" / "history_authority.py"
    sdk_path = root / "sdk" / "__init__.py"
    public_lock_path = root / "01-core" / "_protocol" / "PUBLIC_SURFACE.lock.json"
    try:
        public_violations = _history_authority_public_surface_violations(
            history_path.read_text(encoding="utf-8"),
            sdk_path.read_text(encoding="utf-8"),
            public_lock_path.read_text(encoding="utf-8"),
        )
    except OSError as exc:
        return _fail(
            "GATE-COMMIT-02",
            name,
            f"cannot read history authority public-surface inputs: {exc}",
        )
    if public_violations:
        return _fail(
            "GATE-COMMIT-02",
            name,
            "history authority private/raw seam escaped its boundary",
            evidence={"violations": public_violations},
        )
    return _ok("GATE-COMMIT-02", name)


def check_commit_03_nested_producer_rejected() -> GateResult:
    """producer 内递归 execute 必须在任何 store write 前失败。"""
    from commit_coordinator import CommitCoordinator
    from ports import NestedCommitError
    from operation import new_operation

    name = "nested_commit_producer_rejected"

    class _Doc:
        id = "gate-doc"
        version = 1
        effective_save_policy = "auto_commit"

    class _Store:
        calls = 0

        def commit(self, intent):
            self.calls += 1
            raise AssertionError("nested producer reached store")

    doc, store = _Doc(), _Store()
    coordinator = CommitCoordinator(doc, store)
    op = new_operation(
        command_id="gate.nested", source="system", actor={"user_id": "__gate__"},
        patches=[], reverse_patches=[], document_id=doc.id,
    )
    try:
        coordinator.execute(lambda: coordinator.execute(lambda: op))
    except NestedCommitError:
        pass
    else:
        return _fail("GATE-COMMIT-03", name, "nested execute was accepted")
    if store.calls != 0:
        return _fail("GATE-COMMIT-03", name, "store was called before rejection")
    return _ok("GATE-COMMIT-03", name)


def check_commit_04_pipeline_requires_coordinator() -> GateResult:
    """公开 PipelineSupervisor 默认不得静默启用 legacy canonical publish 旁路。"""
    import threading
