# ---- DB (07-persistence SQLite kernel) ----

def _sqlite_crash_probe_child(
    db_path: str,
    transaction_id: str,
    kind: str,
    crash_point_value: str,
    channel: Any,
) -> None:
    """Spawn-only worker: stop at a real kernel crash point, then os._exit."""
    import os

    try:
        from sqlite_kernel import CrashPoint, SqliteDatabase

        database = SqliteDatabase(Path(db_path))
        target = CrashPoint(crash_point_value)

        def crash_hook(point: Any) -> None:
            if point is not target:
                return
            channel.send(("crash_point", point.value))
            if channel.recv() != "exit-now":
                os._exit(93)
            os._exit(71 if target is CrashPoint.BEFORE_COMMIT else 72)

        database.commit(
            transaction_id,
            kind,
            lambda _unit_of_work: None,
            _test_crash_hook=crash_hook,
        )
        channel.send(("unexpected_return", "commit returned without crashing"))
    except BaseException as exc:
        try:
            channel.send(
                (
                    "error",
                    "%s:%s" % (getattr(exc, "code", type(exc).__name__), str(exc)),
                )
            )
        except BaseException:
            pass
    finally:
        os._exit(90)


def _run_sqlite_crash_probe(
    db_path: Path,
    transaction_id: str,
    kind: str,
    crash_point_value: str,
) -> None:
    """Run one independently spawned crash probe without timing sleeps."""
    import multiprocessing

    context = multiprocessing.get_context("spawn")
    parent_channel, child_channel = context.Pipe(duplex=True)
    process = context.Process(
        target=_sqlite_crash_probe_child,
        args=(str(db_path), transaction_id, kind, crash_point_value, child_channel),
    )
    process.start()
    child_channel.close()
    expected_exit = 71 if crash_point_value == "before_commit" else 72
    try:
        if not parent_channel.poll(20.0):
            raise RuntimeError("child did not reach the crash synchronization point")
        message = parent_channel.recv()
        if message != ("crash_point", crash_point_value):
            raise RuntimeError("child failed before crash point: %r" % (message,))
        parent_channel.send("exit-now")
        process.join(20.0)
        if process.is_alive():
            process.terminate()
            process.join(5.0)
            raise RuntimeError("crash probe child did not exit")
        if process.exitcode != expected_exit:
            raise RuntimeError(
                "crash probe exit=%r, expected=%r"
                % (process.exitcode, expected_exit)
            )
    finally:
        parent_channel.close()
        if process.is_alive():
            process.terminate()
            process.join(5.0)
        process.close()


def check_db_01_sqlite_kernel_safety_profile() -> GateResult:
    """Real connections must enforce the fixed local SQLite safety profile."""
    import os
    import re
    import sqlite3
    import stat
    import tempfile

    from sqlite_kernel import (
        APPLICATION_ID,
        MIGRATIONS,
        FilesystemInfo,
        ReconcileStatus,
        SQLiteKernelError,
        SQLiteSettings,
        SqliteDatabase,
    )

    gate_id = "GATE-DB-01"
    name = "sqlite_kernel_safety_profile"
    try:
        fields = tuple(SQLiteSettings.__dataclass_fields__)
        if fields != ("busy_timeout_ms",):
            return _fail(
                gate_id, name,
                "SQLiteSettings exposes safety downgrade knobs",
                {"fields": fields},
            )
        for raw in ("", "0", "60001", " 5000", "5.0", "-1"):
            try:
                SQLiteSettings.from_env({"ZE_SQLITE_BUSY_TIMEOUT_MS": raw})
                return _fail(gate_id, name, "invalid busy timeout was accepted: %r" % raw)
            except SQLiteKernelError as exc:
                if exc.code != "sqlite_busy_timeout_invalid":
                    return _fail(gate_id, name, "wrong invalid-timeout error: %s" % exc.code)

        kernel_path = (
            _CORE / "02-data-flow" / "07-persistence" / "sqlite_kernel.py"
        )
        kernel_source = kernel_path.read_text(encoding="utf-8")
        env_literals = set(re.findall(r"ZE_SQLITE_[A-Z0-9_]+", kernel_source))
        if env_literals != {"ZE_SQLITE_BUSY_TIMEOUT_MS"}:
            return _fail(
                gate_id, name,
                "SQLite kernel has undeclared/safety env knobs",
                {"env_literals": sorted(env_literals)},
            )
        ops_schema = (
            _CORE.parent / "04-ops" / "01-config-management" / "config_schema.py"
        ).read_text(encoding="utf-8")
        if ops_schema.count('"ZE_SQLITE_BUSY_TIMEOUT_MS"') != 1:
            return _fail(gate_id, name, "ops must own exactly one SQLite env knob")

        with tempfile.TemporaryDirectory(prefix="ze-db-gate-") as tmp:
            root = (Path(tmp).resolve() / "repository")
            path = root / "kernel.sqlite3"
            database = SqliteDatabase(path, settings=SQLiteSettings(1_234))
            first = database.initialize()
            second = database.inspect_profile()
            expected_profiles = (first, second)
            for profile in expected_profiles:
                if (
                    profile.journal_mode != "wal"
                    or profile.synchronous != 2
                    or profile.foreign_keys != 1
                    or profile.trusted_schema != 0
                    or profile.busy_timeout_ms != 1_234
                    or profile.application_id != APPLICATION_ID
                    or profile.user_version != MIGRATIONS[-1].version
                    or not profile.filesystem.is_local
                ):
                    return _fail(
                        gate_id, name, "connection safety profile mismatch",
                        {"profile": repr(profile)},
                    )

            directory_mode = stat.S_IMODE(os.stat(str(root)).st_mode)
            file_info = os.stat(str(path))
            lock_info = os.stat(str(path) + "-bootstrap.lock")
            file_mode = stat.S_IMODE(file_info.st_mode)
            lock_mode = stat.S_IMODE(lock_info.st_mode)
            if (
                directory_mode != 0o700
                or file_mode != 0o600
                or file_info.st_nlink != 1
                or lock_mode != 0o600
                or lock_info.st_nlink != 1
                or not stat.S_ISREG(lock_info.st_mode)
            ):
                return _fail(
                    gate_id, name, "SQLite storage is not private/single-linked",
                    {
                        "directory_mode": oct(directory_mode),
                        "file_mode": oct(file_mode),
                        "links": file_info.st_nlink,
                        "lock_mode": oct(lock_mode),
                        "lock_links": lock_info.st_nlink,
                    },
                )

            absent_path = Path(tmp).resolve() / "absent" / "kernel.sqlite3"
            absent = SqliteDatabase(absent_path)
            absent_result = absent.reconcile("audit-never-created")
            if (
                absent_result.status is not ReconcileStatus.INDETERMINATE
                or absent_result.error_code != "sqlite_database_missing"
                or absent_path.parent.exists()
            ):
                return _fail(
                    gate_id, name,
                    "non-initialize open created or disguised a missing authority",
                    {"result": repr(absent_result), "parent_exists": absent_path.parent.exists()},
                )

            denied_path = (Path(tmp).resolve() / "network" / "kernel.sqlite3")
            denied = SqliteDatabase(
                denied_path,
                _test_filesystem_probe=lambda _path: FilesystemInfo(
                    "nfs", "/network", False, "test network filesystem",
                ),
            )
            try:
                denied.initialize()
                return _fail(gate_id, name, "unproven/network filesystem was accepted")
            except SQLiteKernelError as exc:
                if exc.code != "sqlite_filesystem_unsupported":
                    return _fail(gate_id, name, "wrong filesystem error: %s" % exc.code)

            raw = sqlite3.connect(str(path), isolation_level=None)
            try:
                raw.execute("BEGIN IMMEDIATE")
                raw.execute(
                    "UPDATE schema_migrations SET checksum = ? WHERE version = ?",
                    ("0" * 64, MIGRATIONS[0].version),
                )
                raw.commit()
            finally:
                raw.close()
            try:
                database.inspect_profile()
                return _fail(gate_id, name, "tampered migration checksum was accepted")
            except SQLiteKernelError as exc:
                if exc.code != "sqlite_migration_checksum_mismatch":
                    return _fail(gate_id, name, "wrong migration error: %s" % exc.code)
    except BaseException as exc:
        return _fail(
            gate_id, name,
            "SQLite safety probe failed: %s:%s"
            % (getattr(exc, "code", type(exc).__name__), str(exc)),
        )
    return _ok(gate_id, name, "two fresh profiles + checksum/local-fs/permission probes")


def check_db_02_sqlite_crash_receipt_reconcile() -> GateResult:
    """Spawned os._exit probes must reconcile pre/post-COMMIT truthfully."""
    import tempfile

    from sqlite_kernel import (
        CrashPoint,
        ReconcileStatus,
        SQLiteKernelError,
        SqliteDatabase,
    )

    gate_id = "GATE-DB-02"
    name = "sqlite_crash_receipt_reconcile"
    try:
        with tempfile.TemporaryDirectory(prefix="ze-db-crash-gate-") as tmp:
            path = Path(tmp).resolve() / "repository" / "kernel.sqlite3"
            SqliteDatabase(path).initialize()

            _run_sqlite_crash_probe(
                path, "gate-before-commit", "audit",
                CrashPoint.BEFORE_COMMIT.value,
            )
            before = SqliteDatabase(path).reconcile("gate-before-commit")
            if before.status is not ReconcileStatus.NOT_COMMITTED or before.receipt is not None:
                return _fail(
                    gate_id, name, "pre-COMMIT crash produced a committed receipt",
                    {"result": repr(before)},
                )

            _run_sqlite_crash_probe(
                path, "gate-after-commit", "audit",
                CrashPoint.AFTER_COMMIT_BEFORE_ACK.value,
            )
            after = SqliteDatabase(path).reconcile("gate-after-commit")
            if (
                after.status is not ReconcileStatus.COMMITTED
                or after.receipt is None
                or after.receipt.transaction_id != "gate-after-commit"
                or after.receipt.kind != "audit"
                or not after.receipt.committed_at
            ):
                return _fail(
                    gate_id, name, "post-COMMIT crash receipt was not recoverable",
                    {"result": repr(after)},
                )

            callback_calls = []
            try:
                SqliteDatabase(path).commit(
                    "gate-after-commit",
                    "different-kind",
                    lambda _unit_of_work: callback_calls.append("called"),
                )
                return _fail(gate_id, name, "duplicate transaction id was accepted")
            except SQLiteKernelError as exc:
                if exc.code != "sqlite_transaction_id_conflict":
                    return _fail(gate_id, name, "wrong duplicate-id error: %s" % exc.code)
            if callback_calls:
                return _fail(gate_id, name, "duplicate transaction ran callback before conflict")

            repeated = SqliteDatabase(path).reconcile("gate-after-commit")
            if repeated != after:
                return _fail(gate_id, name, "fresh reconcile changed the durable receipt")
    except BaseException as exc:
        return _fail(
            gate_id, name,
            "SQLite crash probe failed: %s:%s"
            % (getattr(exc, "code", type(exc).__name__), str(exc)),
        )
    return _ok(gate_id, name, "spawn + os._exit before/after COMMIT reconciled")


def _create_sqlite_v1_gate_fixture(path: Path) -> tuple[str, str]:
    """Create an authentic pre-v2 database without mutating runtime registries."""
    import hashlib
    import json
    import os
    import sqlite3

    from sqlite_kernel import APPLICATION_ID, KERNEL_MIGRATION

    created_at = "2026-07-10T00:00:00.000Z"
    receipt_at = "2026-07-10T00:00:01.000Z"
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    os.chmod(str(path.parent), 0o700)
    raw = sqlite3.connect(str(path), isolation_level=None)
    raw.row_factory = sqlite3.Row
    try:
        raw.execute("PRAGMA journal_mode = WAL")
        raw.execute("PRAGMA synchronous = FULL")
        raw.execute("PRAGMA foreign_keys = ON")
        raw.execute("PRAGMA trusted_schema = OFF")
        raw.execute("BEGIN EXCLUSIVE")
        for statement in KERNEL_MIGRATION.statements:
            raw.execute(statement)
        raw.execute(
            "INSERT INTO schema_migrations(version, name, checksum, applied_at) "
            "VALUES (?, ?, ?, ?)",
            (
                KERNEL_MIGRATION.version,
                KERNEL_MIGRATION.name,
                KERNEL_MIGRATION.checksum,
                created_at,
            ),
        )
        raw.execute(
            "INSERT INTO kernel_repository(singleton, authority, created_at) "
            "VALUES (1, 'legacy', ?)",
            (created_at,),
        )
        raw.execute(
            "INSERT INTO transaction_receipts(transaction_id, kind, committed_at) "
            "VALUES ('gate-v1-receipt', 'legacy-test', ?)",
            (receipt_at,),
        )

        # W06.1 fingerprint normalized all whitespace.  Reproduce that exact
        # historical fact so this is a real v1 fixture, not a hand-waved row set.
        rows = raw.execute(
            "SELECT type, name, tbl_name, sql FROM sqlite_schema "
            "WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name, tbl_name"
        ).fetchall()
        schema_rows = tuple(
            (
                row["type"],
                row["name"],
                row["tbl_name"],
                " ".join((row["sql"] or "").strip().rstrip(";").split()),
            )
            for row in rows
        )
        encoded = json.dumps(
            schema_rows, separators=(",", ":"), ensure_ascii=True,
        ).encode("utf-8")
        fingerprint = hashlib.sha256(encoded).hexdigest()
        raw.executemany(
            "INSERT INTO kernel_metadata(key, value) VALUES (?, ?)",
            (
                ("schema_fingerprint", fingerprint),
                ("kernel_schema_version", "1"),
            ),
        )
        raw.execute("PRAGMA application_id = %d" % APPLICATION_ID)
        raw.execute("PRAGMA user_version = 1")
        raw.commit()
    except BaseException:
        raw.rollback()
        raise
    finally:
        raw.close()
    os.chmod(str(path), 0o600)
    return created_at, receipt_at


def _create_sqlite_v2_gate_fixture(path: Path) -> tuple[str, str]:
    """Advance the authentic v1 fixture to exact v2 without running v3."""
    import hashlib
    import json
    import os
    import sqlite3

    from sqlite_schema import BUSINESS_SNAPSHOT_MIGRATION, normalize_schema_sql

    created_at, receipt_at = _create_sqlite_v1_gate_fixture(path)
