def check_project_01_generation_fenced_namespace() -> GateResult:
    """Replace/delete must advance generation and permanently fence old contexts."""
    import tempfile

    from document import Document
    from sdk.project_topology import ProjectTopologyCoordinator

    gate_id = "GATE-PROJECT-01"
    name = "generation_fenced_namespace"

    def build(value: str):
        def _build(root: Path) -> None:
            Document(
                schema_version="1.0.0",
                collaboration_mode="with_save",
                id="p",
                config={"value": value},
            ).save(
                root / "document.json",
            )
        return _build

    def validate(root: Path) -> None:
        Document.open(root / "document.json")

    with tempfile.TemporaryDirectory(prefix="ze-project-gate-") as tmp:
        topology = ProjectTopologyCoordinator(Path(tmp) / "projects")
        topology.initialize(validate=validate)
        created = topology.create("p", build=build("old"), validate=validate)
        with topology.open_live("p") as old_handle:
            pass
        replaced = topology.replace("p", build=build("new"), validate=validate)
        if created.generation != 1 or replaced.generation != 2:
            return _fail(gate_id, name, "create/replace generation did not advance")
        try:
            with topology.activity(old_handle):
                pass
        except Exception as exc:
            if getattr(exc, "code", "") != "project_generation_stale":
                return _fail(gate_id, name, f"wrong stale error: {getattr(exc, 'code', '')}")
        else:
            return _fail(gate_id, name, "obsolete project handle was accepted")
        deleted = topology.delete("p", operation_id="d" * 32)
        proof = topology.intent_status("p", deleted.operation_id)
        if proof.get("status") != "deleted" or proof.get("generation") != 3:
            return _fail(gate_id, name, f"delete proof is not durable: {proof}")
    return _ok(gate_id, name)


def check_project_02_production_lifecycle_wiring() -> GateResult:
    """All production project mutations and writes must consume one lifecycle seam."""
    gate_id = "GATE-PROJECT-02"
    name = "production_lifecycle_wiring"
    root = _CORE.parent
    sources = {
        "bootstrap": (root / "sdk" / "bootstrap.py").read_text(encoding="utf-8"),
        "server": (root / "server.py").read_text(encoding="utf-8"),
        "commit": (
            _CORE / "02-data-flow" / "07-persistence" / "commit_coordinator.py"
        ).read_text(encoding="utf-8"),
        "pipeline": (
            _CORE / "03-commands-operations" / "03-pipeline" / "supervisor.py"
        ).read_text(encoding="utf-8"),
        "mcp": (root / "sdk" / "mcp_bridge.py").read_text(encoding="utf-8"),
        "cli": (root / "scripts" / "ze_command.py").read_text(encoding="utf-8"),
    }
    required = {
        "bootstrap": (
            "ProjectTopologyCoordinator", "topology.initialize(",
            "lifecycle_guard=", "topology.activity(",
        ),
        "server": (
            "_require_topology_request(",
            "/api/projects/{project_id}/intents/{intent_id}",
            "/api/demo-templates/{template_id}/intents/{intent_id}",
            "project_topology_durability_unknown",
            "_require_member_leased",
            "project_generation",
        ),
        "commit": ("with self.lifecycle_guard():",),
        "pipeline": ("with self._lifecycle_guard():",),
        "mcp": ("with lifecycle_guard():",),
        "cli": ("with lifecycle_guard():",),
    }
    for label, needles in required.items():
        for needle in needles:
            if needle not in sources[label]:
                return _fail(gate_id, name, f"{label} is missing lifecycle seam {needle!r}")
    return _ok(gate_id, name)


def check_project_03_duplicate_is_canonical_only() -> GateResult:
    """A duplicate may copy business data, never attempts, logs, exports, or temp state."""
    import tempfile

    from document import Document, read_document_metadata
    from sdk.project_topology import ProjectTopologyCoordinator

    gate_id = "GATE-PROJECT-03"
    name = "duplicate_is_canonical_only"

    def validate(root: Path) -> None:
        Document.open(root / "document.json")

    with tempfile.TemporaryDirectory(prefix="ze-duplicate-gate-") as tmp:
        topology = ProjectTopologyCoordinator(Path(tmp) / "projects")
        topology.initialize(validate=validate)

        def build(root: Path) -> None:
            Document(
                schema_version="1.0.0",
                collaboration_mode="with_save",
                id="source",
            ).save(root / "document.json")
            for name in ("entities", "assets", ".pipelines", "exports"):
                (root / name).mkdir(exist_ok=True)
                (root / name / "entry").write_text(name, encoding="utf-8")
            (root / "oplog.ndjson").write_text("runtime", encoding="utf-8")

        topology.create("source", build=build, validate=validate)

        def rewrite(root: Path) -> None:
            metadata = read_document_metadata(root / "document.json")
            topology._rewrite_staged_document_metadata(
                root,
                expected_version=metadata.version,
                id="copy",
                name=metadata.name,
                acl=metadata.acl,
                config=metadata.config,
            )

        topology.duplicate("source", "copy", rewrite=rewrite, validate=validate)
        copy = topology.path_for("copy")
        if not (copy / "entities" / "entry").is_file() or not (copy / "assets" / "entry").is_file():
            return _fail(gate_id, name, "canonical entities/assets were not copied")
        forbidden = (".pipelines", "exports", "oplog.ndjson")
        leaked = [entry for entry in forbidden if (copy / entry).exists()]
        if leaked:
            return _fail(gate_id, name, f"runtime entries leaked into duplicate: {leaked}")
    return _ok(gate_id, name)


