def check_type_08_envelope_conformance() -> GateResult:
    """信封 round-trip 保真 + sha 不变 + 版本不符结构化拒绝(详尽套件在 test_envelope.py)。"""
    import tempfile
    import type_library as zt
    import envelope as env
    from asset import AssetStore
    from document import DocumentRegistry
    from entity import Entity, ZeError
    name = "type_envelope_conformance"
    with tempfile.TemporaryDirectory() as td:
        store = AssetStore(Path(td) / "src")
        reg = DocumentRegistry()
        zt.apply_preset(reg, "scene")
        doc = reg.build_document(schema_version="1.0.0", name="t")
        ref = store.put(b"BLOB", ext=".png")
        doc.add(Entity(type="scene", name="s", id="s1",
                       data={"width": 100, "height": 100,
                             "background": {"sha256": ref.sha256, "ext": ".png"}}))
        manifest, blobs = env.export_manifest(doc, store)
        if set(blobs) != {ref.sha256}:
            return _fail("GATE-TYPE-08", name, "blob 收集与引用不符")
        reg2 = DocumentRegistry()
        zt.apply_preset(reg2, "scene")
        doc2 = reg2.build_document(schema_version="1.0.0", name="t2")
        dst = AssetStore(Path(td) / "dst")
        created, warnings = env.import_manifest(doc2, dst, manifest, blobs)
        if len(created) != 1 or doc2.get("scene", "s1").data != doc.get("scene", "s1").data:
            return _fail("GATE-TYPE-08", name, "round-trip 字段不保真")
        if dst.get(ref) != b"BLOB":
            return _fail("GATE-TYPE-08", name, "blob sha/内容漂移")
        try:
            env.import_manifest(doc2, dst, {"schema": "ze.manifest.scene.v99", "entities": []})
            return _fail("GATE-TYPE-08", name, "版本闸未拦 v99")
        except ZeError as e:
            if e.code != "manifest_version_unsupported":
                return _fail("GATE-TYPE-08", name, f"wrong code: {e.code}")
    return _ok("GATE-TYPE-08", name)


def check_type_10_broker_proposal_conformance() -> GateResult:
    """broker 协商层:opportunistic 导入恰好落地 proposal.accept、不半导入 required_field_unmet
    实体、锚子物按 AP-03 丢弃、L0 资产可读(详尽套件在 test_broker.py)。"""
    import tempfile
    import type_library as zt
    import envelope as env
    from asset import AssetStore, AssetRef
    from document import DocumentRegistry
    from entity import Entity
    name = "type_broker_proposal_conformance"

    def _anno_target():
        reg = DocumentRegistry()
        reg.set_collaboration_mode("with_save")
        reg.declare_entity_type(name="asset_item", schema=zt.archetype("asset_item"),
                                collaboration_unit=True)
        reg.declare_entity_type(name="annotation", schema=zt.archetype("annotation"),
                                collaboration_unit=False)
        return reg.build_document(schema_version="1.0.0", name="anno")

    with tempfile.TemporaryDirectory() as td:
        store = AssetStore(Path(td) / "src")
        reg = DocumentRegistry()
        zt.apply_preset(reg, "timeline")
        src = reg.build_document(schema_version="1.0.0", name="seq")
        img = store.put(b"FRAME", ext=".png")
        src.add(Entity(type="sequence", name="片", id="seq1",
                       data={"width": 1920, "height": 1080}))
        src.add(Entity(type="asset_item", name="素材", id="a1",
                       data={"media": {"sha256": img.sha256, "ext": ".png"}, "kind": "image"}))
        src.add(Entity(type="track", name="轨", id="t1", data={"order": 0, "kind": "visual"}))
        src.add(Entity(type="clip", name="段", id="c1",
                       data={"track": 0, "start": 0, "duration": 4}))
        manifest, blobs = env.export_manifest(src, store)

        # 异类目标:asset_item 走 L2;sequence undeclared;track/clip foreign_anchor_child
        target = _anno_target()
        prop = env.compute_ingest_proposal(manifest, target)
        if prop["level"] != "L2" or [a["src_bucket"] for a in prop["accept"]] != ["asset_item"]:
            return _fail("GATE-TYPE-10", name, f"accept 撮合错:{prop['accept']}")
        reasons = {d["reason"] for d in prop["drop"]}
        if not {"foreign_anchor_child", "undeclared"} <= reasons:
            return _fail("GATE-TYPE-10", name, f"drop 理由缺失:{reasons}")

        # opportunistic 导入恰好落 accept 集 + 资产可读
        sub_m, sub_b = env.filter_manifest_to_proposal(manifest, blobs, prop)
        dst = AssetStore(Path(td) / "dst")
        created, _ = env.import_manifest(target, dst, sub_m, sub_b)
        if {(e.type, e.id) for e in created} != {("asset_item", "a1")}:
            return _fail("GATE-TYPE-10", name, f"落地集与 accept 不符:{[(e.type, e.id) for e in created]}")
        if target.list("annotation") or dst.get(AssetRef(sha256=prop["assets"][0], ext=".png")) != b"FRAME":
            return _fail("GATE-TYPE-10", name, "落地越界或资产不可读")

        # 自毁防护:annotation 源(asset_item + annotation,an1.target 必填→a1),目标只声明 annotation
        # → annotation 必填 target 悬空 → 整体不收、不半导入
        rega = DocumentRegistry()
        rega.set_collaboration_mode("with_save")
        rega.declare_entity_type(name="asset_item", schema=zt.archetype("asset_item"),
                                 collaboration_unit=True)
        rega.declare_entity_type(name="annotation", schema=zt.archetype("annotation"),
                                 collaboration_unit=False)
        asrc = rega.build_document(schema_version="1.0.0", name="anno-src")
        asrc.add(Entity(type="asset_item", name="图", id="a1",
                        data={"media": {"sha256": img.sha256, "ext": ".png"}, "kind": "image"}))
        asrc.add(Entity(type="annotation", name="框", id="an1",
                        data={"target": {"$ref": "asset_item/a1"}, "label": "x"}))
        reg3 = DocumentRegistry()
        reg3.set_collaboration_mode("with_save")
        reg3.declare_entity_type(name="annotation", schema=zt.archetype("annotation"),
                                 collaboration_unit=False)
        only = reg3.build_document(schema_version="1.0.0", name="only")
        m2, b2 = env.export_manifest(asrc, store)
        p2 = env.compute_ingest_proposal(m2, only)
        if p2["accept"] or "required_field_unmet" not in {d["reason"] for d in p2["drop"]}:
            return _fail("GATE-TYPE-10", name, "自毁防护失败:必填 ref 悬空未拦")
        sm2, sb2 = env.filter_manifest_to_proposal(m2, b2, p2)
        c2, _ = env.import_manifest(only, AssetStore(Path(td) / "d3"), sm2, sb2)
        if c2 or only.list("annotation"):
            return _fail("GATE-TYPE-10", name, "自毁防护失败:半导入了悬空实体")
    return _ok("GATE-TYPE-10", name)


def check_type_11_harvest_rule_legality() -> GateResult:
    """broker 收割规则(L1)合法性:build_document fail-fast 拦非法 rule(必填 entity_ref / 未覆盖必填 /
    坏角色格式 / 桶未声明),合法 rule(media→asset_item 补 kind)放行(详尽套件 test_broker.py)。"""
    import type_library as zt
    from document import DocumentRegistry
    from entity import ZeError
    name = "type_harvest_rule_legality"

    def _reg(rule, buckets):
        r = DocumentRegistry()
        r.set_collaboration_mode("with_save")
        for bn, arch in buckets:
            r.declare_entity_type(name=bn, schema=zt.archetype(arch), collaboration_unit=True)
        r.declare_harvest_rule(**rule)
        return r

    # 合法 rule 须放行
    try:
        _reg({"when_role": "ze.field.media@1", "into_bucket": "asset_item",
              "supply_required": {"kind": "image"}},
             (("asset_item", "asset_item"),)).build_document(schema_version="1.0.0")
    except ZeError as e:
        return _fail("GATE-TYPE-11", name, f"合法 rule 被误拒: {e}")

    # 非法 rule 须 fail-fast(validation_failed)
    cases = [
        ({"when_role": "ze.field.bbox_xyxy@1", "into_bucket": "annotation"},
         (("annotation", "annotation"),)),                                  # 必填 entity_ref
        ({"when_role": "ze.field.media@1", "into_bucket": "asset_item"},
         (("asset_item", "asset_item"),)),                                  # 未覆盖必填 kind
        ({"when_role": "media", "into_bucket": "asset_item", "supply_required": {"kind": "image"}},
         (("asset_item", "asset_item"),)),                                  # 坏角色格式
        ({"when_role": "ze.field.media@1", "into_bucket": "ghost", "supply_required": {"kind": "image"}},
         (("asset_item", "asset_item"),)),                                  # 桶未声明
    ]
    for rule, buckets in cases:
        try:
            _reg(rule, buckets).build_document(schema_version="1.0.0")
            return _fail("GATE-TYPE-11", name, f"非法 rule 未拦: {rule}")
        except ZeError as e:
            if e.code != "validation_failed":
                return _fail("GATE-TYPE-11", name, f"wrong code {e.code} for {rule}")
    return _ok("GATE-TYPE-11", name)


def check_type_06_provenance_annotations() -> GateResult:
    """x-ze-use / x-ze-archetype / x-ze-sealed / x-ze-ext 注解必在。"""
    import type_library as zt
    from fragments import ARCHETYPES
    if zt.field("label").get("x-ze-use") != "ze.field.label@1":
        return _fail("GATE-TYPE-06", "type_provenance_annotations", "x-ze-use 缺失")
    for short in ARCHETYPES:
        s = zt.archetype(short)
        if s.get("x-ze-archetype") != f"ze.archetype.{short}@{ARCHETYPES[short]['version']}":
            return _fail("GATE-TYPE-06", "type_provenance_annotations",
                         f"{short} x-ze-archetype 缺失/失真")
        for name in s.get("x-ze-sealed", []):
            if name not in s["properties"]:
                return _fail("GATE-TYPE-06", "type_provenance_annotations",
                             f"{short} sealed {name!r} 不在 properties")
    ext = zt.archetype("review", extend={"x_severity": {"type": "integer"}})
    if ext["properties"]["x_severity"].get("x-ze-ext") is not True:
        return _fail("GATE-TYPE-06", "type_provenance_annotations", "x-ze-ext 缺失")
    return _ok("GATE-TYPE-06", "type_provenance_annotations")


