# ==============================================================
# Runner
# ==============================================================

def run_all() -> list[GateResult]:
    """跑全部 gate; 返回 [GateResult]."""
    return [gate_fn() for gate_id, gate_fn in GATES.items()]


def run_one(gate_id: str) -> GateResult:
    """跑指定 gate."""
    if gate_id not in GATES:
        return _skip(gate_id, "<unknown>", f"unknown gate {gate_id!r}")
    return GATES[gate_id]()


def run_leaf(leaf_prefix: str) -> list[GateResult]:
    """跑某叶子的全部 gate. leaf_prefix='DOC' / 'ENT' / 'AST' ..."""
    prefix = f"GATE-{leaf_prefix.upper()}-"
    return [gate_fn() for gid, gate_fn in GATES.items() if gid.startswith(prefix)]


# ==============================================================
# CLI 入口
# ==============================================================

def main(argv: list[str] | None = None) -> int:
    """python audit_gates.py [--all] [--gate GATE-ID] [--leaf DOC]."""
    import argparse
    parser = argparse.ArgumentParser(description="Run audit gates")
    grp = parser.add_mutually_exclusive_group()
    grp.add_argument("--all", action="store_true", help="run all gates")
    grp.add_argument("--gate", help="run specific gate (e.g. GATE-OP-02)")
    grp.add_argument("--leaf", help="run leaf gates (e.g. DOC / ENT / AST)")
    args = parser.parse_args(argv)

    if args.gate:
        results = [run_one(args.gate)]
    elif args.leaf:
        results = run_leaf(args.leaf)
    else:
        results = run_all()

    n_ok = n_fail = n_skip = 0
    for r in results:
        marker = {"PASS": "✅", "FAIL": "❌", "SKIP": "⏭"}.get(r.status, "?")
        print(f"{marker} {r.gate_id}: {r.name}")
        if r.status == "FAIL" and r.msg:
            print(f"   原因: {r.msg}")
        elif r.status == "SKIP" and r.msg:
            print(f"   跳过: {r.msg}")
        if r.status == "PASS":
            n_ok += 1
        elif r.status == "FAIL":
            n_fail += 1
        else:
            n_skip += 1
    print()
    print(f"总计: {len(results)}; PASS {n_ok}, FAIL {n_fail}, SKIP {n_skip}")
    return 0 if n_fail == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
